(function(global){
'use strict';
const RA=global.RA=global.RA||{};
const D=(w,p)=>RA.D(w,p);
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+(w==='unpaid worker'?'unpaid':w.toLowerCase().replaceAll(' ','-'))});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('untreated','Transparent un- + treated: left without medical or other treatment.',C('untreated.s1','health','The untreated wound became infected because nobody cleaned or dressed it.','伤口一直没有清洗或包扎，后来感染了。','untreated wound/infection; leave untreated','形容词，指未接受治疗或处理。','No care was given to the wound.','未处理'),M('The untreated wound was cleaned and dressed by a nurse.','The treated wound was cleaned and dressed by a nurse.','Cleaning and dressing are treatment, so untreated is inaccurate.','meaning'),[Q(1,'An untreated wound has…','received no care','healed fully','been dressed carefully','The adjective means treatment has not happened.','meaning'),Q(1,'Why did it become infected?','Nobody cleaned or dressed it','A nurse cleaned it hourly','It was covered with sterile gauze','The context gives lack of care as the cause.','context'),Q(1,'Choose the natural phrase.','leave an infection untreated','an untreatedly infection','untreated of infection','Untreated is an adjective after leave + object.','grammar'),Q(1,'Here un- means…','not or without','again','before','The prefix negates treated.','word-formation')]);
P('untrue','Untrue combines un- with true, explicitly negating truth.',C('untrue.s1','news','The rumour that the school would close proved untrue when the council released its plan.','市政委员会公布计划后，学校将关闭的传言被证明不实。','untrue rumour/claim; prove untrue','形容词，指虚假或不忠实于事实。','The official plan disproved the rumour.','不真实'),M('The report was untrue because every detail matched verified records.','The report was true because every detail matched verified records.','Details confirmed by records support true, not untrue.','meaning'),[Q(1,'A rumour that proves untrue is…','shown to be false','confirmed by evidence','hidden from the council','Untrue means not true.','meaning'),Q(1,'What disproved the school rumour?','The council released its plan','A pupil repeated it','The school changed its name','The official plan supplied contrary facts.','context'),Q(1,'Which phrase is correct?','an untrue claim','an untruth claim','a claim untrueness','Untrue is an adjective modifying claim.','grammar'),Q(1,'Untrue is formed from…','un- plus true','truth plus -ed','true plus plural -s','The negative prefix changes the adjective’s meaning.','word-formation')]);
P('untrustworthy','Untrustworthy adds negative un- to trustworthy: not deserving reliance.',C('untrustworthy.s1','law','The witness seemed untrustworthy because she changed her story whenever the lawyer asked for details.','这名证人似乎不可信，因为律师每次追问细节，她都会改变说法。','untrustworthy witness/source; seem untrustworthy','形容词，指可能撒谎、失信或不诚实。','Her inconsistent account makes reliance unsafe.','不可信'),M('The untrustworthy witness gave the same honest account at every interview.','The trustworthy witness gave the same honest account at every interview.','A consistent honest account supports trustworthy, the opposite.','meaning'),[Q(1,'Why did the witness seem untrustworthy?','She kept changing her account','She presented a signed record','She answered consistently','Changing stories make her unreliable.','context'),Q(1,'An untrustworthy source should be…','checked against reliable evidence','accepted as proof immediately','used as the sole authority','The adjective warns that reliance is not justified.','meaning'),Q(1,'Complete: The witness seemed ___ to the jury.','untrustworthy','untrustworthiness','untrustworthily','An adjective follows seemed; the other choices are a noun and an adverb.','grammar'),Q(1,'The prefix un-…','negates trustworthy','means highly trustworthy','names a trusting person','The word means not worthy of trust.','word-formation')]);
P('untwist','Untwist combines un- and twist to describe reversing a twist.',C('untwist.s1','repair','She untwisted the wire until the trapped bird could spread its wing.','她把铁丝解开，直到被困的小鸟能展开翅膀。','untwist a wire/cord; untwist from around','动词，指反向转动以解开扭结。','Reversing the twist freed the bird.','解开'),M('He untwisted the cord by winding it tighter around the post.','He twisted the cord tighter around the post.','Winding tighter adds a twist rather than undoing one.','meaning'),[Q(1,'To untwist wire is to…','turn it the other way until straight','wind it tighter','cut it into pieces','Untwist reverses twisting.','meaning'),Q(1,'What did untwisting allow?','The bird could spread its wing','The wire formed a knot','The bird changed cages','The wire no longer trapped it.','context'),Q(1,'Complete naturally: ___ the cord from the handle.','Untwist','Untwisting to','Untwist at around','From marks what the cord is being freed from.','grammar'),Q(1,'Un- in untwist indicates…','undoing the twist','a person who twists','a future action','It signals reversal here.','word-formation')]);
P('unusable','Unusable is un- + usable: not fit for use in its present condition.',C('unusable.s1','transport','Floodwater covered the only road, making it unusable for buses and emergency vehicles.','洪水淹没了唯一的道路，使公交车和应急车辆无法通行。','unusable road/equipment; render unusable','形容词，指损坏或不合适到无法使用。','Vehicles could not use the flooded road.','无法使用'),M('The unusable bridge carried heavy trucks safely all afternoon.','The usable bridge carried heavy trucks safely all afternoon.','A bridge that carries trucks safely is usable.','meaning'),[Q(1,'Why was the road unusable?','Floodwater covered it','It had just been repaired','It was wide enough for buses','The water prevented vehicles using it.','context'),Q(1,'An unusable tool is…','not fit to be used','ready for work','more useful than expected','Un- negates usable.','meaning'),Q(1,'Choose the correct phrase.','render the road unusable','render the road unusably','render unusable the road by its','Unusable is an adjective complement of render.','grammar'),Q(1,'Unusable is built from…','un- plus usable','use plus -ed','usual plus -ly','The prefix makes usable negative.','word-formation')]);
P('unused','Unused is un- + used; senses include idle, never used, unproductive, and unfamiliar.',[C('unused.s1','property','The unused room at the back of the house has been empty for years.','房子后面的空房间多年没有使用。','unused room/space; remain unused','形容词，指当前没有使用。','The room is idle now.','未使用'),C('unused.s2','product','The printer is unused, still sealed in its original box.','打印机仍未使用，封在原包装盒里。','brand-new and unused; unused equipment','形容词，指从未用过、保持原样。','The seal shows it has never been operated.','崭新未用'),C('unused.s3','land','Much unused land outside town could support a community garden.','城外许多未开发土地可以建社区花园。','unused land/resources; put to use','形容词，指未被有效利用。','The land has no productive use yet.','未开发'),C('unused.s4','experience','After years in the tropics, she was unused to such a cold winter.','在热带生活多年后，她不习惯如此寒冷的冬天。','be unused to something; unused to the climate','be unused to 表示不习惯。','She lacks experience with this climate.','不习惯')],M('He was unused to the cold but found it familiar and comfortable from the first moment.','He was used to the cold and found it familiar and comfortable.','Familiarity means used to, not unused to.','meaning'),[Q(1,'An unused room is…','not in use now','occupied every day','newly built for immediate use','Sense 1 concerns current use.','meaning'),Q(2,'Why is the printer unused?','Its seal is intact','It prints daily','It has been repaired','Sense 2 means never used.','context'),Q(3,'Unused land has…','not been put to productive use','been fully farmed','no possible owner','Sense 3 concerns underused resources.','meaning'),Q(4,'She is unused to the cold: she…','is not accustomed to it','has never felt any temperature','works in a cold room','Be unused to means not familiar with.','grammar')]);
P('unusual','Unusual is un- + usual; context may mean abnormal, rare, distinctive, or unfamiliar.',[C('unusual.s1','mechanics','An unusual noise from the engine made the driver stop and inspect it.','发动机发出异常声响，司机因此停车检查。','unusual noise/symptom; seem unusual','指偏离常态、可能预示问题。','The sound is abnormal and concerning.','异常'),C('unusual.s2','frequency','It is unusual for this office to close before five on a weekday.','这间办公室在工作日五点前关门并不常见。','unusual for someone to do; unusually early','指罕见或出乎意料。','Early closing seldom happens.','罕见'),C('unusual.s3','style','Her unusual mix of old maps and bright fabric made the exhibit memorable.','她把旧地图与鲜艳布料结合起来的独特方式让展览令人难忘。','unusual style/design; something unusual','指因不同寻常而有趣或吸引人。','The distinctive design attracts attention.','独特'),C('unusual.s4','food','The market sells unusual spices from distant countries.','市场出售来自遥远国家的陌生香料。','unusual food/spices; unusual variety','指来自远方、令人陌生的。','These imported spices are unfamiliar locally.','异域')],M('The engine made an unusual noise, exactly like its normal sound, and worried nobody.','The engine made a normal noise, exactly like its usual sound, and worried nobody.','A normal sound is not unusual.','meaning'),[Q(1,'Why stop at the unusual engine noise?','It differed from the normal sound','It was quieter than ever','The driver reached the office','Sense 1 is abnormal and concerning.','context'),Q(2,'If early closing is unusual, it is…','rare at that office','the daily schedule','required every weekday','Sense 2 concerns frequency.','meaning'),Q(3,'The exhibit’s unusual style was…','distinctive and memorable','an exact copy of every other exhibit','empty of objects','Sense 3 can be attractive because it differs.','context'),Q(4,'Unusual spices from distant countries are…','unfamiliar imports','ordinary local salt','expired products','Sense 4 highlights unfamiliar origin.','meaning')]);
P('unveil','Unveil combines un- and veil: reveal publicly or literally remove a covering.',[C('unveil.s1','announcement','The studio will unveil its new game at the technology fair next month.','工作室将在下月科技展上首次公布新游戏。','unveil a product/plan; publicly unveil','首次向公众展示或公布。','People will see the game for the first time.','揭晓'),C('unveil.s2','art','At the ceremony, the artist unveiled the statue by pulling away its cloth.','仪式上，艺术家掀开布罩，揭开雕像。','unveil a statue/portrait; unveil a cover','指揭开遮盖物。','The cloth was physically removed.','揭开')],M('The studio unveiled the game but kept every image and detail hidden from everyone.','The studio announced the game but kept every image and detail hidden from everyone.','Unveil means reveal, not keep entirely hidden.','meaning'),[Q(1,'What will the studio unveil?','A new game at the fair','A cloth over an old statue','The fair’s ticket prices','Sense 1 is a first public presentation.','context'),Q(2,'The artist unveiled the statue by…','removing its cloth cover','painting it while covered','moving it away','Sense 2 is literal uncovering.','meaning'),Q(1,'Which collocation is natural?','unveil a new plan','unveil secretly from nobody forever','unveil to cover a statue','Figuratively, unveil means reveal a plan.','collocation'),Q(2,'The literal image behind unveil is…','removing a veil or cover','putting a veil on','seeing something repeatedly','The older physical sense motivates revealing.','word-formation')]);
P('unverified','Unverified is un- + verified: not yet checked against evidence or official records.',C('unverified.s1','media','The editor held the unverified report until another source confirmed the names.','编辑暂缓发布未经核实的报道，直到另一个来源确认姓名。','unverified claim/report; remain unverified','形容词，指尚未通过证据核验。','The names still need independent checking.','未核实'),M('The report was unverified after two independent records confirmed every name.','The report was verified after two independent records confirmed every name.','Independent confirmation verifies the report.','context'),[Q(1,'Why did the editor hold the report?','The names needed confirmation','It was already fully corrected','It was too short','Unverified information still needs checking.','context'),Q(1,'An unverified claim should be…','checked before being treated as fact','shared as proven','used instead of official records','The adjective signals a lack of verification.','meaning'),Q(1,'Choose the correct phrase.','an unverified report','a report unverify','a report verifiedless','Unverified is the adjective form.','grammar'),Q(1,'The prefix un- means…','not yet','again','by everyone','It negates verified.','word-formation')]);
P('unwary','Unwary combines un- + wary and describes failure to notice danger or deception.',C('unwary.s1','scams','The fake ticket offer targeted unwary fans who skipped the seller check.','假票交易专门针对没有核验卖家的粗心球迷。','unwary customers; take advantage of the unwary','指没有留意危险或骗局的。','The fans missed a precaution that could expose fraud.','不警觉'),M('The unwary buyer spotted the forged seal immediately and refused to pay.','The wary buyer spotted the forged seal immediately and refused to pay.','Noticing a warning sign shows wariness.','meaning'),[Q(1,'Who are the unwary fans?','Fans who miss the scam risk','Fans who check every seller','Fans with valid tickets','Unwary means not alert to danger.','meaning'),Q(1,'What did they skip?','Checking the seller','Reading the match score','Choosing a seat','That check could have exposed the fraud.','context'),Q(1,'Which phrase is idiomatic?','take advantage of the unwary','take advantage to unwary','the unwary of customers','The unwary can refer to unwary people collectively.','grammar'),Q(1,'Un- changes wary to mean…','not cautious','more cautious','cautious again','The prefix negates the quality.','word-formation')]);
P('unwelcome','Unwelcome combines un- with welcome and means unpleasant to receive or not gladly admitted.',C('unwelcome.s1','reaction','The tax increase was an unwelcome surprise for families already struggling with bills.','对已为账单发愁的家庭来说，增税是个不受欢迎的意外。','unwelcome news/guest/surprise; make someone unwelcome','形容词，指令人不快或不被乐于接受。','The news brings an unwanted burden.','不受欢迎'),M('The unwelcome guest was warmly invited in, and everyone was delighted to see him.','The welcome guest was warmly invited in, and everyone was delighted to see him.','A wanted, warmly received guest is welcome.','meaning'),[Q(1,'Why was the tax increase unwelcome?','It added a burden to struggling families','It reduced every bill','It was a birthday gift','Unwelcome describes an unpleasant thing to receive.','context'),Q(1,'An unwelcome visitor is…','not gladly received','eagerly expected','someone without an address','It describes the reception given.','meaning'),Q(1,'Which phrase is natural?','an unwelcome surprise','an unwelcome to surprise','surprise unwelcomeing','Unwelcome is an adjective before surprise.','grammar'),Q(1,'The prefix un-…','negates welcome','means welcome again','turns it into a verb','It makes the positive reception negative.','word-formation')]);
P('unwell','Unwell is a polite adjective for feeling ill, from mild sickness to illness that prevents attendance.',[C('unwell.s1','health','Mina felt unwell after lunch and went home before her headache grew worse.','午饭后米娜感到不舒服，在头痛加重前回了家。','feel/be unwell; look unwell','形容词，指身体不适或轻微生病。','She feels sick and her headache is worsening.','身体不适'),C('unwell.s2','workplace','Several employees reported that they were unwell and could not come to work.','几名员工报告身体抱恙，无法来上班。','be unwell today; report oneself unwell','礼貌委婉地说病到无法工作或上学。','Illness explains the employees’ absence.','抱恙')],M('She said she was unwell but also perfectly healthy and eager to work all day.','She said she was well and perfectly healthy, so she could work all day.','Perfect health contradicts the usual meaning of unwell.','meaning'),[Q(1,'Why did Mina go home?','She felt ill and her headache might worsen','She had completed all her work','She was asked to lead a meeting','Sense 1 is feeling sick.','context'),Q(2,'The employees said they were unwell to explain…','why they could not work that day','why they received a promotion','why the office moved','Sense 2 politely explains illness-related absence.','context'),Q(1,'Complete: She has been feeling ___ all morning.','unwell','unwellness','unwellly','Feeling takes an adjective describing her condition.','grammar'),Q(2,'In a workplace notice, unwell is often…','a polite way to say ill','a job title','a synonym for vacation','It is a tactful illness expression.','register')]);
P('unwieldy','Unwieldy combines un- and wieldy: awkward to move or too complex to manage.',[C('unwieldy.s1','objects','The unwieldy cabinet would not fit through the narrow doorway, even when tilted.','即使倾斜，笨重的柜子也无法通过狭窄门口。','unwieldy box/furniture; carry an unwieldy object','指过大或过重、难以搬动的。','The cabinet is hard to maneuver through the door.','笨重'),C('unwieldy.s2','administration','The agency replaced its unwieldy approval system with a simpler online process.','该机构用更简单的在线流程取代了难管理的审批系统。','unwieldy system/process; an unwieldy bureaucracy','指规模或复杂性使其难以管理的。','Too many steps make the system hard to control.','难管理')],M('The unwieldy cabinet slipped through the narrow doorway with one hand and no effort.','The manageable cabinet slipped through the narrow doorway with one hand and no effort.','An object moved effortlessly is not physically unwieldy.','meaning'),[Q(1,'Why was the cabinet unwieldy?','It was awkward to maneuver through the door','It folded into a pocket','It was small enough to carry easily','Sense 1 is physical difficulty of handling.','context'),Q(2,'Why replace the unwieldy system?','It was too complex to manage','It was too simple to understand','It processed requests instantly','Sense 2 concerns organizational complexity.','context'),Q(1,'Which phrase is correct?','an unwieldy piece of furniture','an unwieldy small enough to carry','furniture unwieldily cabinet','Unwieldy is an adjective modifying furniture.','grammar'),Q(2,'A system is unwieldy when…','its complexity makes it hard to manage','it is simple and efficient','it is physically heavy only','This sense concerns manageability.','meaning')]);
P('unwilling','Unwilling is un- + willing: lacking desire or readiness; it can also mean resistant to hearing an argument.',[C('unwilling.s1','agreement','The tenants were unwilling to sign the lease until the repair costs were clarified.','维修费用得到澄清前，租户们不愿签署租约。','be unwilling to do something; reluctant and unwilling','指不想做或尚未准备好做某事。','They do not want to sign before the costs are clear.','不愿意'),C('unwilling.s2','listening','The committee remained unwilling to hear objections from residents.','委员会仍不愿听取居民的反对意见。','unwilling to listen/accept; an unwilling audience','指不愿听取或接受请求、论点。','It refuses to consider opposing views.','不肯听取')],M('The committee was unwilling to hear objections, so it invited every resident to speak and considered each point.','The committee was willing to hear objections, so it invited every resident to speak and considered each point.','Listening and considering objections shows willingness.','meaning'),[Q(1,'Why would the tenants not sign yet?','They wanted repair costs clarified','They accepted every term','There was no lease','Sense 1 concerns desire or readiness.','context'),Q(2,'An unwilling committee here…','refuses to hear objections','asks residents to object','has already changed its decision','Sense 2 means resistant to listening.','meaning'),Q(1,'Complete the pattern: unwilling ___ sign.','to','at','for','Unwilling is followed by an infinitive with to.','grammar'),Q(2,'Un- in unwilling…','negates willing','means willing again','turns willing into a noun','It expresses a lack of willingness.','word-formation')]);
P('unwillingly','Unwillingly is unwilling + -ly, describing an action done reluctantly.',C('unwillingly.s1','compliance','He unwillingly signed the form after his supervisor said the deadline could not be extended.','主管表示截止日期无法延后后，他不情愿地签了表格。','sign/agree unwillingly; act unwillingly','副词，指勉强地、不情愿地做事。','He complies but would prefer not to.','不情愿地'),M('She accepted the invitation willingly but did so unwillingly and without hesitation.','She accepted the invitation willingly and without hesitation.','Willing acceptance contradicts the adverb unwillingly.','meaning'),[Q(1,'How did he sign?','Reluctantly, after hearing the deadline stood','Eagerly, before anyone asked','By refusing to touch the form','Unwillingly means without wanting to.','context'),Q(1,'Someone who agrees unwillingly…','agrees despite reluctance','agrees with excitement','refuses to answer','The adverb describes reluctant agreement.','meaning'),Q(1,'Complete: He signed the form ___.','unwillingly','unwilling','unwillingness','The adverb modifies the action signed; the other forms are adjective and noun.','word-formation'),Q(1,'Which sentence is correct?','They unwillingly gave up the extra day off.','They were unwillingly to give up the day off.','They unwillingness gave up the day off.','The adverb modifies gave up.','grammar')]);
P('unwillingness','Unwillingness adds noun-forming -ness to unwilling and names reluctance or refusal to act.',C('unwillingness.s1','negotiation','The team’s unwillingness to compromise prolonged the negotiations for another month.','团队不愿妥协，使谈判又延长了一个月。','unwillingness to cooperate/compromise; show unwillingness','名词，指不愿或拒绝采取行动的状态。','Refusal to compromise blocks progress.','不愿意'),M('Her willingness to cooperate stalled the meeting because she refused every proposal.','Her unwillingness to cooperate stalled the meeting because she refused every proposal.','Refusing proposals demonstrates unwillingness, not willingness.','meaning'),[Q(1,'What prolonged the negotiations?','The team refused to compromise','The team agreed immediately','The room was unavailable','Unwillingness blocked progress.','context'),Q(1,'Unwillingness names…','a state of not wanting or being ready to act','eagerness to act immediately','the completion of a task','It is the noun for being unwilling.','meaning'),Q(1,'Choose the natural phrase.','unwillingness to cooperate','unwillingness for cooperate','unwillingness cooperating to','The noun is commonly followed by to + verb.','grammar'),Q(1,'The suffix -ness…','forms a noun for a quality or state','marks past tense','forms a comparative','It names the state of being unwilling.','word-formation')]);
P('unwind','Unwind is un- + wind: undo a winding, or figuratively relax after tension.',[C('unwind.s1','repair','He unwound the rope from the fence post before putting it away.','他把绳子从篱笆柱上解下来后收好。','unwind a rope/thread; unwind from around','指把缠绕的东西解开。','The rope is released by reversing its winding.','解开缠绕'),C('unwind.s2','leisure','After finals, I unwind with a slow walk and leave my phone at home.','期末考试结束后，我会把手机留在家里，慢慢散步放松。','unwind after work; unwind by doing something','指休息、缓解紧张。','The walk helps the speaker relax.','放松')],M('After finals, she unwound by checking work messages every minute and worrying about deadlines.','After finals, she relaxed by setting work messages aside and taking a quiet walk.','Constant work and worry oppose the relaxing sense of unwind.','meaning'),[Q(1,'What did he unwind?','A rope from the post','A metal gate','A painted sign','Sense 1 means undo what is wound around something.','context'),Q(2,'How does the speaker unwind?','By taking a slow walk without a phone','By checking work messages','By sitting another exam','Sense 2 means relax.','context'),Q(1,'What is the past form of unwind?','unwound','unwinded','unwinding','Unwind is an irregular verb with past unwound.','grammar'),Q(2,'After a stressful day, to unwind is to…','relax and become less tense','add urgent tasks','tie up loose ropes','The figurative sense is relaxation.','meaning')]);
P('unwittingly','Unwittingly is unwitting + -ly and means doing something without realizing it.',C('unwittingly.s1','privacy','She unwittingly revealed the password in a screenshot showing her open notes.','她在一张显示打开笔记的截图中无意泄露了密码。','unwittingly reveal/disclose; act unwittingly','副词，指没有意识到后果地、无意中。','She did not notice the password was visible.','无意中'),M('He unwittingly revealed the secret on purpose after planning it for weeks.','He deliberately revealed the secret after planning it for weeks.','A planned disclosure is deliberate, not unwitting.','meaning'),[Q(1,'How did the password become visible?','She shared the screenshot without noticing','She deliberately printed it on a poster','The account had no password','Unwittingly means without realizing.','context'),Q(1,'To unwittingly cause trouble is to do so…','without being aware of it','after planning harm','for the purpose of causing it','The adverb marks an unintended action.','meaning'),Q(1,'Which form is the adverb?','unwittingly','unwittingness','unwitting','The -ly ending forms the manner adverb.','word-formation'),Q(1,'Choose the natural sentence.','He unwittingly sent the draft to the wrong address.','He unwittingly was sending without realize.','He sent unwittingly draft wrong address on purpose.','Unwittingly modifies the sending action.','grammar')]);
P('unwrap','Unwrap adds un- to wrap to mean removing an object’s wrapping.',C('unwrap.s1','gifts','The child unwrapped the present slowly, careful not to tear the paper.','孩子慢慢拆开礼物，小心不撕破包装纸。','unwrap a gift/package; unwrap carefully','动词，指去掉包裹物外面的包装。','The paper is taken off the present.','拆包装'),M('She unwrapped the gift by adding three new layers of paper.','She wrapped the gift by adding three new layers of paper.','Adding paper wraps an object; unwrapping removes it.','meaning'),[Q(1,'What did the child unwrap?','A present','Bare string','An object that had no covering','Unwrap removes an existing wrapping.','context'),Q(1,'To unwrap food is to…','remove its covering','add a layer around it','cook it until soft','The verb describes taking off the wrap.','meaning'),Q(1,'Which past form is correct?','unwrapped','unwrapping yesterday','unwrappened','The regular past form doubles p and adds -ed.','grammar'),Q(1,'The prefix un- here expresses…','undoing the wrapping','wrapping again','a state of being wrapped','It reverses the action of wrap.','word-formation')]);
P('unyielding','Unyielding combines un- and yielding, describing refusal to give way physically or in a position.',C('unyielding.s1','negotiation','The negotiator remained unyielding and rejected every proposal that weakened the safety rule.','谈判代表态度坚决，拒绝所有削弱安全规则的提案。','unyielding resistance/stance; remain unyielding','形容词，指不让步、不弯曲或不改变立场。','He refuses to give way on the rule.','不屈服'),M('The unyielding negotiator gave in immediately and accepted the first proposal.','The yielding negotiator gave in immediately and accepted the first proposal.','Giving in means yielding, unlike an unyielding stance.','meaning'),[Q(1,'What showed the negotiator was unyielding?','He rejected proposals weakening the rule','He accepted all terms immediately','He left before hearing any offer','He refused to give way on this point.','context'),Q(1,'An unyielding material would…','resist bending or changing shape','bend under a light touch','dissolve in water','The adjective can describe physical rigidity.','meaning'),Q(1,'Which phrase is natural?','an unyielding stance','an unyieldingness stance','a stance unyieldingly person','Unyielding is an adjective modifying stance.','grammar'),Q(1,'Un- in unyielding…','negates yielding or giving way','means yield repeatedly','names the person yielding','It expresses the opposite of yielding.','word-formation')]);
P('up','Up is an Old English adverb/preposition used for higher position, movement along a route, and completion.',[C('up.s1','direction','The child looked up at the kite caught above the trees.','孩子抬头看着挂在树上方的风筝。','look/go/climb up; up in the air','指朝较高位置或处于较高位置。','The gaze moves toward a higher point.','向上'),C('up.s2','route','We walked up the river path until we reached the old mill.','我们沿河边小路向上游走到旧磨坊。','walk/drive up a road; up the river','沿路或河流朝远端、源头方向。','They follow the river toward its source.','沿着'),C('up.s3','completion','Time is up, so please put down your pencils.','时间到了，请放下铅笔。','time is up; use something up','表示用完、结束或发生。','The allowed period has ended.','结束')],M('The exam time was up, so the students had another hour to finish.','The exam time was not up, so the students had another hour to finish.','If time is up, the allowed period has ended.','meaning'),[Q(1,'The child looked up toward…','a higher place','the floor','the river mouth','Sense 1 marks upward direction.','meaning'),Q(2,'They walked up the river toward…','its source or far end','the sea only','a point below the path','Sense 2 can mark travel upstream.','meaning'),Q(3,'When time is up, it is…','finished','extended by an hour','not yet started','Sense 3 marks completion.','context'),Q(1,'Complete: use ___ all the milk.','up','over','under','Use up means consume completely.','collocation')]);
P('up to','Up to combines up and to; it marks a limit, responsibility, ability, or activity.',[C('up to.s1','limit','The trail is open up to the ridge, but the summit path is closed.','步道开放到山脊处，但山顶路已关闭。','up to a limit/number; extend up to','达到某个时间、数量或界限为止。','The ridge is the endpoint.','到达上限'),C('up to.s2','choice','Whether we take the train or drive is up to you.','坐火车还是开车由你决定。','be up to someone; it is up to you','由某人决定或负责。','You have the choice.','由你决定'),C('up to.s3','ability','After resting, she felt up to the two-hour hike.','休息后，她觉得自己能应付两小时徒步。','feel/be up to a task; not up to it','身体或能力足以应付某事。','Rest restored her ability.','能胜任'),C('up to.s4','activity','The children were quiet, so their parents wondered what they were up to.','孩子们安静得反常，父母想知道他们在做什么。','what are you up to; be up to something','指正在做某事，有时暗示不妥当。','The silence makes their parents suspicious.','在做什么')],M('The trail goes up to the ridge, and hikers may continue along the closed summit path.','The trail goes up to the ridge, but hikers cannot continue on the closed summit path.','The stated endpoint does not grant access beyond a closed trail.','meaning'),[Q(1,'The open trail ends up to…','the ridge','the closed summit','the valley below','Sense 1 identifies the boundary.','context'),Q(2,'If the choice is up to you, who decides?','You','The train conductor','Nobody','Sense 2 assigns the decision to you.','meaning'),Q(3,'Feeling up to a hike means…','feeling able to manage it','feeling unable to stand','being required to organize it','Sense 3 concerns capability.','meaning'),Q(4,'“What are they up to?” asks…','what they are doing','how high they climbed','who owns their house','Sense 4 asks about someone’s activity.','meaning')]);
P('up-to-date','Up-to-date is a compound adjective meaning current in information or modern in equipment.',[C('up-to-date.s1','records','Keep the contact list up-to-date when staff members change phone numbers.','员工更换电话号码时，请及时更新联系人名单。','keep records up-to-date; an up-to-date list','信息更新到当前时点。','The list should show the newest details.','最新'),C('up-to-date.s2','technology','The clinic installed up-to-date scanners that produce clearer images.','诊所安装了现代化扫描仪，可以生成更清晰的图像。','up-to-date equipment/facilities; modern and up-to-date','设备或风格现代先进。','The scanners use current technology.','现代化')],M('The contact list was up-to-date but showed every employee’s old phone number.','The contact list was outdated because it showed every employee’s old phone number.','Old numbers mean the list is not current.','meaning'),[Q(1,'Why update the contact list?','To show staff members’ newest numbers','To preserve their old numbers','To remove all names','Sense 1 concerns current information.','context'),Q(2,'Up-to-date scanners are…','modern and using current technology','obsolete and broken','manual typewriters','Sense 2 concerns modern equipment.','meaning'),Q(1,'Before a noun, which spelling is standard?','an up-to-date record','an up to date record','an up-to-dately record','The compound adjective takes hyphens before a noun.','spelling'),Q(1,'Up-to-date means current as of…','the present','the distant past','a scheduled future date only','The phrase means updated through now.','meaning')]);
P('upbeat','Upbeat is a compound from up + beat, describing a positive mood or outlook.',C('upbeat.s1','attitude','Despite the delay, the project leader gave an upbeat update and praised the team’s progress.','尽管项目延期，负责人仍作了积极的汇报，并赞扬团队进展。','an upbeat mood/tone; remain upbeat','形容词，指情绪或看法积极乐观。','The speaker stresses progress and encouragement.','乐观'),M('The upbeat announcement said the project had failed and there was no hope.','The gloomy announcement said the project had failed and there was no hope.','A hopeless announcement is gloomy, not upbeat.','meaning'),[Q(1,'How was the project update?','Positive and encouraging','Angry and hopeless','Unrelated to the project','Upbeat means positive in mood or outlook.','context'),Q(1,'An upbeat outlook is…','optimistic','despairing','without any opinion','The adjective expresses a positive attitude.','meaning'),Q(1,'Complete: The report struck an ___ tone.','upbeat','upbeatly','upbeatness','An adjective modifies tone; the other choices are an adverb and noun.','grammar'),Q(1,'Which is closest to upbeat?','optimistic','hopeless','indifferent','An upbeat speaker emphasizes positive prospects.','meaning')]);
P('upbraid','Upbraid comes from Middle English upbreiden and Old English upbregdan, literally “bring forth as a ground for censure,” from up + bregdan, “move quickly, intertwine.”',[C('upbraid.s1','coaching','The coach upbraided the players for ignoring the safety instructions.','教练因队员无视安全指示而严厉斥责他们。','upbraid someone for something; be upbraided','因过错严厉责骂。','They are scolded for a specific fault.','斥责'),C('upbraid.s2','formal review','The inquiry upbraided officials for failing to act after warnings arrived.','调查因官员收到警告后未行动而正式谴责他们。','upbraid officials for a failure; formally upbraid','正式责备未履行职责。','The report assigns blame for inaction.','谴责')],M('The coach upbraided to the players for ignoring the safety instructions.','The coach upbraided the players for ignoring the safety instructions.','Upbraid takes the person being blamed as its direct object, without to.','grammar'),[Q(1,'Why did the coach upbraid the players?','They ignored safety instructions','They followed every rule','They won the match','Sense 1 is scolding someone for a fault.','context'),Q(2,'Why were officials upbraided?','They failed to act on warnings','They sent timely warnings','They had no public role','Sense 2 is formal blame for neglected duty.','context'),Q(1,'Choose the usual construction.','upbraid someone for a mistake','upbraid someone of a mistake','upbraid to someone a mistake','The pattern is upbraid someone for something.','grammar'),Q(1,'Upbraid means…','reproach severely','congratulate warmly','ignore completely','It means scold or blame.','meaning')]);
P('upbringing','Upbringing is formed from bring up, meaning raise a child, plus -ing; it names childhood care, teaching, and manners.',[C('upbringing.s1','family','Her strict upbringing included daily chores and careful lessons in reading.','她在严格的成长环境中每天做家务，并认真学习阅读。','have a strict/comfortable upbringing; childhood upbringing','指成长过程中受到的照料和教育。','The example describes how she was raised.','成长经历'),C('upbringing.s2','manners','His polite upbringing showed when he thanked every volunteer.','他向每位志愿者道谢的举止体现了良好教养。','good upbringing; show one’s upbringing','指成长中学到的礼貌和行为方式。','His manners reflect what he learned while growing up.','教养')],M('Her upbringing meant she had grown old before her parents began to raise her.','Her upbringing means the care and teaching she received while growing up.','Upbringing describes childhood rearing, not aging before being raised.','meaning'),[Q(1,'What shaped her upbringing?','Daily chores and reading lessons','A job at age forty','One library visit','Sense 1 concerns childhood care and teaching.','context'),Q(2,'What did his polite upbringing show?','Manners learned while he was raised','The school building design','His height','Sense 2 concerns learned behavior.','context'),Q(1,'Choose the idiomatic phrase.','a strict upbringing','an upbringing strictness','upbringingly child','Upbringing is a noun modified by strict.','grammar'),Q(1,'The verb related to upbringing is…','bring up a child','bring down a curtain','bring about a meeting','Bring up can mean raise a child.','word-formation')]);
P('upcoming','Upcoming is formed from up + come and describes something happening or being released soon.',[C('upcoming.s1','events','Details of the upcoming election will be announced after the debate.','辩论后将公布即将举行的选举详情。','upcoming event/election; in upcoming weeks','指不久后将发生的。','The election is near in time.','即将到来'),C('upcoming.s2','publishing','Her upcoming novel is set in Paris and will appear this autumn.','她即将出版的小说以巴黎为背景，将于今年秋天面世。','upcoming book/film; upcoming release','指不久后准备出版或发行的作品。','The novel is not released yet but will be soon.','即将推出')],M('The upcoming film came out ten years ago and has not been shown since.','The old film came out ten years ago and has not been shown since.','An event ten years in the past is not upcoming.','meaning'),[Q(1,'When will details of the election be announced?','After the debate, before the upcoming election','After the election is forgotten','Before the previous election','Upcoming points to the near future.','context'),Q(2,'Her upcoming novel is…','soon to be published','already released ten years ago','cancelled long ago','Sense 2 concerns a near-future release.','meaning'),Q(1,'Which phrase is natural?','an upcoming event','an upcomingly event','an event upcomings','Upcoming is an adjective before event.','grammar'),Q(1,'Upcoming most directly means…','coming soon','finished long ago','never planned','It refers to the near future.','meaning')]);
P('update','Update is from up + date; it means make information current, modernize something, or provide a current report.',[C('update.s1','records','Update your address so the clinic has your current details.','请更新地址，以便诊所掌握你的最新信息。','update a record/list; update someone on something','补充新信息，使资料准确。','The new address replaces the old one.','更新资料'),C('update.s2','technology','The school updated its computers with faster processors.','学校为电脑换上更快的处理器，使设备现代化。','update a system/software; update equipment','使系统或设备变得更现代。','New processors improve the older machines.','升级改造'),C('update.s3','report','Here is an update on the storm: it has changed direction and weakened.','以下是风暴最新情况：它已改变方向并减弱。','give/provide an update; latest update','提供最新情况的简短报告。','The statement summarizes new developments.','最新情况')],M('Please update your address by deleting the new one and keeping the outdated address.','Please update your address by replacing the old one with the current one.','Updating makes information current rather than preserving obsolete details.','meaning'),[Q(1,'Why update the clinic form?','To show the current address','To preserve an old address','To change the computers','Sense 1 adds current facts.','context'),Q(2,'What did the school update?','Its computers with faster processors','The students’ home addresses','A weather report','Sense 2 means modernize the equipment.','context'),Q(3,'An update on the storm is…','a short report with the newest facts','a prediction from last year','a piece of old equipment','Sense 3 names the latest report.','meaning'),Q(3,'Which sentence uses update as a noun?','Here is an update on the storm.','Update your address now.','They update the computers.','The first sentence uses it as a report noun.','grammar')]);
P('updraft','Updraft combines up + draft and names a rising current of air.',C('updraft.s1','aviation','The glider caught an updraft over the ridge and climbed without an engine.','滑翔机在山脊上空遇到上升气流，不用发动机便升高。','catch/ride an updraft; a strong updraft','名词，指迅速上升的气流。','Rising air lifts the glider.','上升气流'),M('The glider sank because an updraft pushed it rapidly toward the ground.','The glider rose because an updraft lifted it through the air.','An updraft moves air upward, not toward the ground.','meaning'),[Q(1,'What lifted the glider?','A rising current of air','A rope from the ridge','Its engine','An updraft is rising air.','context'),Q(1,'A pilot may catch an updraft to…','gain height','lose all lift','land underwater','Rising air can carry a glider upward.','meaning'),Q(1,'Which collocation describes a glider using rising air?','catch an updraft','catch a downdraft','avoid a crosswind','Catch an updraft means meet a rising air current.','collocation'),Q(1,'Up- in updraft refers to…','movement upward','movement underground','a sideways turn','The draft carries air upward.','word-formation')]);
P('upend','Upend combines up + end: set an object on an end or tip it over onto one end.',[C('upend.s1','objects','He upended the crate so its open end faced upward and used it as a seat.','他把箱子倒过来，让开口朝上，并把它当座位。','upend a box/crate; turn something upended','把物体立到一端或翻转。','The crate is turned onto an end.','倒置'),C('upend.s2','accident','The cart upended in the ditch when its front wheel struck a stone.','手推车前轮撞上石头后在沟里翻倒。','a cart upends; be thrown over','物体倾翻并倒到一端。','The cart tips over.','翻倒')],M('He upended the crate while leaving it flat on its base as before.','He upended the crate by turning it onto one end.','Leaving it flat does not turn the crate onto an end.','meaning'),[Q(1,'How was the crate used as a seat?','It was turned so an end faced upward','It stayed flat and empty','It was broken into boards','Sense 1 means set on an end.','context'),Q(2,'What caused the cart to upend?','Its wheel struck a stone','It was parked safely','A driver removed its wheel','Sense 2 is accidental tipping.','context'),Q(1,'What is the simple past of upend?','upended','upendded','upending yesterday','The verb takes regular -ed.','grammar'),Q(2,'A cart that upended has…','tipped over','rolled smoothly forward','been repaired','The verb describes overturning.','meaning')]);
P('upgrade','Upgrade combines up + grade and means raise to a better level, improve quality, or the improvement itself.',[C('upgrade.s1','technology','We upgraded the operating system to the newest version before the security audit.','安全审计前，我们把操作系统升级到最新版本。','upgrade software/system; upgrade to a version','改变为更好或更新的版本。','The system now runs the newest release.','升级版本'),C('upgrade.s2','service','The hotel upgraded its rooms with better lighting and quieter windows.','酒店为客房配备了更好的照明和更安静的窗户。','upgrade a room/service; upgrade facilities','提高服务或建筑品质。','The improvements raise room quality.','提升品质'),C('upgrade.s3','result','The free upgrade gives passengers extra legroom on the new aircraft.','免费升级让乘客在新飞机上获得更多腿部空间。','get/receive an upgrade; a free upgrade','指提升到更高等级的改进或新版本。','Passengers receive an improved service level.','升级')],M('The hotel upgraded its rooms by removing the better lights and installing broken windows.','The hotel downgraded its rooms by removing the better lights and installing broken windows.','Removing improvements lowers quality; it is downgrading.','meaning'),[Q(1,'What did the software upgrade do?','Installed the newest operating-system version','Returned to an old release','Removed the security audit','Sense 1 means change to a newer version.','context'),Q(2,'How did the hotel upgrade its rooms?','By adding better lighting and quieter windows','By removing all windows','By cutting service quality','Sense 2 means improve quality.','context'),Q(3,'What did the free upgrade give passengers?','More legroom at a higher service level','A smaller seat','A bill for an aircraft','Sense 3 names an improvement received.','meaning'),Q(1,'Which sentence uses upgrade as a noun?','The free upgrade gave us more space.','We upgrade the software.','They upgraded the rooms.','The first sentence names an improvement.','grammar')]);
P('upheaval','Upheaval is related to upheave, “lift up”; it names sudden major change, disorder, or geological lifting.',[C('upheaval.s1','politics','The reforms caused an upheaval in local government and changed how services were funded.','改革在地方政府引发巨变，也改变了公共服务的拨款方式。','political/social upheaval; cause upheaval','指造成巨大变化的突然事件。','The reforms substantially alter the system.','剧变'),C('upheaval.s2','disorder','The strike threw the whole industry into upheaval for several weeks.','罢工使整个行业陷入数周的混乱。','throw something into upheaval; in upheaval','指严重混乱或动荡状态。','Normal operations are disrupted.','动荡'),C('upheaval.s3','geology','The earthquake left visible upheaval along the fault, lifting one side of the road.','地震在断层沿线留下明显隆起，把道路一侧抬高。','geological upheaval; tectonic upheaval','地质学中指地表突然向上移动。','The earth surface physically rises.','地壳隆起')],M('The strike caused upheaval, yet every factory operated normally and nothing changed.','The strike caused upheaval, disrupting normal factory operations.','Upheaval involves major change or disorder, not unchanged operations.','meaning'),[Q(1,'What changed in local government?','How services were funded','The location of the town','The weather forecast','Sense 1 is sudden major change.','context'),Q(2,'Why was the industry in upheaval?','The strike disrupted normal operations','Factories had closed years earlier','Demand stayed unchanged','Sense 2 means a state of disorder.','context'),Q(3,'What did geological upheaval do?','Lifted part of the road along a fault','Lowered the sea everywhere','Painted the road','Sense 3 is upward earth movement.','meaning'),Q(1,'Upheaval is related to…','upheave, meaning lift up','uphold, meaning defend','upwind, meaning face the wind','The word evokes something lifted or violently changed.','word-formation')]);
P('uphill','Uphill combines up + hill and means moving up a slope or requiring hard effort.',C('uphill.s1','effort','Getting funding was an uphill battle for the small research team.','对这个小型研究团队来说，争取资金是一场艰难奋斗。','uphill climb/battle; work uphill','字面指上坡，也比喻需要艰苦努力。','Funding required sustained effort.','艰难'),M('Winning funds was an uphill battle, and the money arrived effortlessly on the first try.','Winning funds was easy, and the money arrived effortlessly on the first try.','Effortless success is not an uphill battle.','meaning'),[Q(1,'Why was funding an uphill battle?','It required substantial effort','It arrived automatically','The team had no research','Figuratively uphill means difficult.','context'),Q(1,'An uphill walk goes…','up a slope','down into a valley','around a level field','The literal sense follows the rising ground.','meaning'),Q(1,'Choose the usual collocation.','an uphill struggle','an uphill sleep','an uphill recipe','Uphill often modifies struggle or battle for a hard task.','collocation'),Q(1,'In “uphill battle,” uphill is…','a metaphor for difficulty','a sailing direction','a unit of time','Climbing effort maps to overcoming a hard task.','word-formation')]);
P('uphold','Uphold combines up + hold and means defend a principle or confirm a prior decision.',[C('uphold.s1','law','Judges must uphold the law even when a decision is unpopular.','即使裁决不受欢迎，法官也必须维护法律。','uphold the law/right/principle; uphold a standard','维护法律、权利或原则。','The judges defend the law’s authority.','维护'),C('uphold.s2','court','The appeal court upheld the verdict after reviewing the evidence.','上诉法院审查证据后维持了原判。','uphold a ruling/verdict; verdict upheld','确认先前决定正确并予以维持。','The earlier verdict remains in force.','维持裁决')],M('The appeal court upheld the verdict by overturning it and ordering a new trial.','The appeal court overturned the verdict and ordered a new trial.','Overturning reverses a verdict; upholding leaves it in force.','meaning'),[Q(1,'What must judges uphold?','The law','An unpopular rumour','A court building','Sense 1 means maintain a principle.','context'),Q(2,'What did the appeal court uphold?','The earlier verdict','A new-trial request','The evidence file','Sense 2 means confirm a prior decision.','context'),Q(1,'Complete: ___ the law.','uphold','uphelding','uphold to','Uphold takes a direct object.','grammar'),Q(2,'If a ruling is upheld, it is…','left valid after review','automatically erased','never considered','The decision remains in force.','meaning')]);
P('upkeep','Upkeep combines up + keep and names continuing maintenance and its cost.',C('upkeep.s1','property','The upkeep of the old house is expensive because its roof needs frequent repairs.','老房子的维护费用很高，因为屋顶需要经常维修。','cost of upkeep; maintenance and upkeep','指持续保养、维修及相关费用。','Frequent repairs create ongoing costs.','维护费用'),M('The upkeep of the house was free, with no repairs or care ever needed.','The upkeep of the house was costly because repairs and care were needed.','Upkeep refers to continuing care, often with an ongoing cost.','meaning'),[Q(1,'Why is upkeep expensive?','The roof needs frequent repairs','The house never needs care','The house was sold','Upkeep includes ongoing repairs.','context'),Q(1,'Upkeep is closest to…','maintenance','purchase','decoration only','It is continuing care and repair.','meaning'),Q(1,'Which phrase is natural?','the cost of upkeep','the upkeeping cost','upkeep to a house','The noun appears in cost of upkeep.','grammar'),Q(1,'Does upkeep mean only the purchase price?','No, it concerns continuing care and repair','Yes, only the first payment','Yes, the house address','Its sense includes maintenance and its cost.','meaning')]);
P('upland','Upland combines up + land and describes high inland country or things situated there.',[C('upland.s1','geography','Sheep graze on the uplands above the village, far from the coast.','绵羊在远离海岸、位于村庄上方的高地上吃草。','upland area/farm; the uplands','指远离海岸的高地。','The grazing land lies high inland.','高地'),C('upland.s2','farming','Farmers grow hardy oats on the upland slopes of the valley.','农民在山谷高地坡地上种耐寒燕麦。','upland crops/soil; upland slopes','作形容词，指位于高地的。','The slopes are high and inland.','高地的')],M('They grazed sheep on the upland coast below sea level.','They grazed sheep on the lowland coast below sea level.','High inland uplands are not low coastal land.','meaning'),[Q(1,'Where are the sheep grazing?','High inland land above the village','A beach below sea level','A city market','Sense 1 is high country away from the sea.','context'),Q(2,'Upland slopes are…','slopes situated in high land','slopes under the ocean','flat city streets','Sense 2 uses upland as an adjective.','meaning'),Q(1,'Choose the natural phrase.','upland farming','farming uplandly','an uplands crop','Upland can modify farming.','grammar'),Q(1,'The word land in upland refers to…','an area of ground','a ship’s sail','an hour','The compound names elevated country.','word-formation')]);
P('uplift','Uplift means lift upward; figuratively it raises morale, and in geology it can mean earth elevation.',C('uplift.s1','morale','The coach’s speech uplifted the tired team before the final match.','决赛前教练的讲话鼓舞了疲惫的队员。','uplift someone’s spirits; feel uplifted','使人更有希望或精神振奋，也可表示向上抬升。','The speech improves morale.','鼓舞'),M('The uplifting speech made the tired team feel hopeless and defeated.','The discouraging speech made the tired team feel hopeless and defeated.','Uplift means raise spirits, not make people hopeless.','meaning'),[Q(1,'What did the speech do?','Raised the team’s spirits','Ended the match','Injured a player','Uplift figuratively means encourage.','context'),Q(1,'Music that uplifts a listener…','makes the listener feel more hopeful','makes the listener shorter','confuses every lyric','This sense concerns mood.','meaning'),Q(1,'Complete: The speech ___ the team.','uplifted','uplifted up','upliftingly the','Uplift takes the team as its object.','grammar'),Q(1,'The literal sense of uplift is…','lift upward','hold back','move sideways','The compound transparently means lift up.','word-formation')]);
P('upload','Upload combines up + load; it means send a file from a local device to a server, or the transfer itself.',[C('upload.s1','computing','Upload the photo to the secure server before noon for the editor to review.','请在中午前把照片上传到安全服务器，让编辑审阅。','upload a file/photo; upload to a server','把文件从本地设备发送到服务器或互联网。','The file moves from device to server.','上传'),C('upload.s2','computing','The upload failed halfway, so the video never appeared on the website.','上传进行到一半失败，因此视频没有出现在网站上。','a file upload; complete/cancel an upload','上传文件或上传这一行为。','Here upload names the transfer.','上传过程')],M('Upload the file from the server back to your laptop so the website receives it.','Download the file from the server to your laptop; upload it from your laptop to the server.','Upload sends a local file to a server; the first direction is reversed.','meaning'),[Q(1,'Where should the photo go?','From the device to the server','From a server to a printer only','Into a paper folder','Sense 1 is a transfer to a server.','context'),Q(2,'What failed halfway?','The video-file transfer','The recording of the video','The website design','Sense 2 uses upload as a noun.','context'),Q(1,'Choose the normal collocation.','upload a file to a server','upload a file from a server to the internet','upload at a server a file to','The standard direction is local device to server.','collocation'),Q(2,'In “the upload failed,” upload is…','a noun naming a transfer','an adjective describing a server','a past-tense verb','The article the introduces the noun.','grammar')]);
P('upmarket','Upmarket combines up + market and describes goods for affluent buyers or a move toward a premium style.',[C('upmarket.s1','retail','They opened an upmarket hotel with spacious rooms and a private dining room.','他们开了一家高档酒店，提供宽敞客房和私人餐厅。','upmarket hotel/shop; upmarket goods','指面向富裕消费者、价格和档次较高。','It targets guests willing to pay more.','高档'),C('upmarket.s2','business','The clothing brand went upmarket by choosing finer fabrics and raising prices.','这个服装品牌采用更好的面料并提高价格，逐渐走向高端。','go/move upmarket; an upmarket image','指变得更昂贵或风格更高档。','The company changes products and positioning.','走向高端')],M('The upmarket shop targets budget shoppers by selling only the cheapest basic goods.','The discount shop targets budget shoppers by selling only the cheapest basic goods.','Cheap basic goods for budget buyers are not upmarket.','meaning'),[Q(1,'Who is the hotel aimed at?','Customers seeking higher-end service','Travelers seeking only the cheapest bed','People who never travel','Sense 1 concerns affluent customers.','context'),Q(2,'How did the brand go upmarket?','It chose finer fabrics and raised prices','It lowered prices and cut quality','It stopped selling clothes','Sense 2 is a shift toward a premium position.','context'),Q(1,'Which phrase is natural?','an upmarket restaurant','an upmarketly restaurant','restaurant upmarketing','Upmarket functions as an adjective.','grammar'),Q(1,'An upmarket product is usually…','higher-priced and premium','the cheapest available','not sold in a market','The word denotes the upper end of a market.','meaning')]);
P('upon','Upon is a formal or literary variant of on; it also marks sequence and appears in phrases meaning based on.',[C('upon.s1','location','The old town sits upon a hill overlooking the harbour.','古镇坐落在一座俯瞰港口的小山上。','upon a surface; depend upon','正式或文学用法，表示在某表面上。','The town is located on the hill.','在……之上'),C('upon.s2','sequence','Upon arrival, visitors should report to the front desk.','抵达后，访客应到前台报到。','upon arrival/hearing; immediately upon','表示某事发生时或紧接其后。','Reporting follows arrival.','一……就'),C('upon.s3','basis','The tax is calculated upon income earned during the year.','税款按本年度所得收入计算。','based upon; calculate upon a basis','正式表达中表示依据、基于。','Income is the basis of the calculation.','依据')],M('Upon arrival at the station, the travelers reported there before they arrived.','Before arriving at the station, the travelers reported there.','Upon arrival means at the time of arriving, not before.','meaning'),[Q(1,'Where is the old town?','On a hill above the harbour','Below the harbour water','Inside the front desk','Sense 1 is the formal locative use of on.','context'),Q(2,'Upon arrival means…','when or immediately after arriving','before setting out','a week after leaving','Sense 2 marks the event that triggers the next action.','meaning'),Q(3,'The tax is calculated upon…','income earned during the year','the visitors’ arrival time','the hill height','Sense 3 means on the basis of.','context'),Q(1,'Upon in formal writing often means…','on','underneath','against','It is a more formal variant of on.','meaning')]);
P('upper','Upper is the comparative form of up and describes a higher position; as a noun it can name the top part of a shoe.',[C('upper.s1','location','Write your name in the upper corner of the form, above the signature line.','请把姓名写在表格上方的角落里，位于签名栏上方。','upper corner/level; upper part','形容词，指相对于另一部分位置更高。','The corner lies higher on the page.','上方的'),C('upper.s2','clothing','The shoe’s upper is made of soft leather, while its sole is rubber.','鞋面由柔软皮革制成，鞋底则是橡胶。','shoe upper; leather upper','名词，指鞋的上部，或牙齿等上方部分。','It is the part above the sole.','鞋面')],M('The shoe’s upper is the rubber layer that touches the ground.','The shoe’s sole is the rubber layer that touches the ground.','The upper is the top of the shoe; the sole touches the ground.','meaning'),[Q(1,'Where should the name go?','In the higher corner above the signature','Below the signature line','On the back of the chair','Sense 1 means higher in position.','context'),Q(2,'What is a shoe upper?','The part above the sole','The rubber part underfoot','The lace hole only','Sense 2 names the top section of a shoe.','meaning'),Q(1,'Upper is related to which base word?','up','upon','under','It is the comparative form of up.','word-formation'),Q(2,'Which material makes the shoe’s upper?','Soft leather','Rubber from the sole','Paper from the box','The context explicitly contrasts leather upper with rubber sole.','context')]);
P('upper arm','Upper arm is a compound naming the arm segment above the forearm, between shoulder and elbow.',C('upper arm.s1','anatomy','The bruising is on her upper arm, between the shoulder and elbow.','她的上臂有瘀青，位置在肩膀和肘部之间。','upper arm muscle; pain in the upper arm','名词，指肩膀与肘部之间的手臂部分。','The location distinguishes it from the forearm.','上臂'),M('The doctor examined his upper arm below the wrist and above the hand.','The doctor examined his forearm below the elbow and above the wrist.','The region between wrist and hand is not the upper arm.','meaning'),[Q(1,'Where was the bruising?','Between her shoulder and elbow','Between her wrist and fingers','On her knee','That region is the upper arm.','context'),Q(1,'Which muscle belongs to the upper arm?','One between shoulder and elbow','One in the calf','One between fingers','The term names that arm segment.','meaning'),Q(1,'Which phrase is natural?','a sore upper arm','an upperly arm','an arm of upperness','Upper modifies the noun arm.','grammar'),Q(1,'The word upper here distinguishes it from the…','forearm','upper floor','shoulder blade only','The upper arm is above the forearm.','meaning')]);
P('upper floor','Upper floor is a compound for a building level above the one currently referred to.',C('upper floor.s1','buildings','The bedrooms are on the upper floor, while the kitchen is downstairs.','卧室在楼上，而厨房在楼下。','on the upper floor; reach the upper floor','名词，指建筑中更高的一层。','The bedrooms are above the kitchen level.','上层'),M('The bedrooms are on the upper floor, which is below the basement.','The bedrooms are on the lower floor, which is above the basement.','A floor above the ground level is not below the basement.','meaning'),[Q(1,'Where are the bedrooms?','On a floor above the kitchen','In the basement','Outside the building','The context states they are on the upper floor.','context'),Q(1,'An upper floor is…','a building level above the current one','the lowest underground level','the roof itself','The phrase describes a higher storey.','meaning'),Q(1,'Choose the correct preposition.','on the upper floor','in the upper floor at','to upper floor of','We say rooms are on a floor.','grammar'),Q(1,'Upper in this phrase means…','higher in position','more expensive','earlier in time','The building level is physically higher.','meaning')]);
P('upper house','Upper house is the compound name for the smaller, usually more senior chamber of a two-chamber parliament.',C('upper house.s1','government','The bill passed the upper house without amendment before returning to the lower chamber.','法案未经修订便通过了上议院，随后返回下议院。','the upper house of parliament; pass the upper house','名词，指两院制议会中通常较资深、规模较小的一院。','It is one chamber of the legislature.','上议院'),M('The bill passed the upper house, the larger and less senior chamber of parliament.','The bill passed the lower house, the larger chamber of parliament.','The upper house is usually the more senior and smaller chamber.','meaning'),[Q(1,'What happened to the bill?','It passed the upper house unchanged','It was rejected by both chambers','It became a court ruling','The context says it passed without amendment.','context'),Q(1,'In a two-chamber parliament, the upper house is usually…','the smaller, more senior chamber','the larger chamber of ordinary voters','the supreme court','That is the source entry’s parliamentary sense.','meaning'),Q(1,'Which phrase is correct?','the upper house of parliament','the upper house in parliament’s upstairs','an upper house parliament','The standard phrase uses of parliament.','grammar'),Q(1,'Upper house is a political term for…','one chamber of a legislature','a private home on a hill','a parliamentary election','The compound names a parliamentary chamber.','meaning')]);
P('uppermost','Uppermost combines upper + -most and means highest in place or dominant in thought.',C('uppermost.s1','priority','Safety was uppermost in the engineers’ minds as they tested the bridge.','工程师测试桥梁时，安全始终是他们最优先考虑的事。','uppermost in someone’s mind; the uppermost shelf','指位置最高的，或思想中最重要、最突出的。','Safety dominated their attention.','最优先'),M('Safety was uppermost in their minds, so they ignored it completely.','Safety was uppermost in their minds, so they checked every risk.','If safety dominates attention, ignoring it contradicts uppermost.','meaning'),[Q(1,'What was uppermost in the engineers’ minds?','Safety','The bridge’s paint color','The lunch menu','It dominated their attention.','context'),Q(1,'The uppermost shelf is…','the highest shelf','the lowest drawer','the widest shelf','Uppermost marks the highest position.','meaning'),Q(1,'Which phrase is natural?','uppermost in my mind','uppermost at my mind','uppermost by my mind','The idiom uses in someone’s mind.','grammar'),Q(1,'The suffix -most in uppermost marks…','the highest degree or position','a past action','a person who performs an action','It forms a superlative-like “highest” adjective.','word-formation')]);
P('upright','Upright comes from Old English upriht and describes a vertical position or morally honest conduct.',[C('upright.s1','objects','Keep the bottle upright so the liquid does not spill through the loose cap.','把瓶子直立放好，以免液体从松动的瓶盖漏出。','stand/hold upright; keep something upright','指直立、不倾斜。','The bottle must remain vertical.','直立'),C('upright.s2','ethics','The judge was known as an upright person who never accepted gifts from litigants.','这位法官以正直著称，从不收当事人的礼物。','an upright citizen/judge; morally upright','指品行诚实正直。','Refusing improper gifts shows integrity.','正直'),C('upright.s3','posture','She stood upright to see over the tall hedge.','她挺直身体站着，以便越过高树篱看过去。','sit/stand upright; upright posture','指身体处于垂直姿势。','Her body is straight rather than bent.','挺直')],M('Keep the bottle upright by laying it flat on its side.','Keep the bottle horizontal by laying it flat on its side.','A bottle lying on its side is not upright.','meaning'),[Q(1,'How should the bottle be placed?','Vertically, not tilted','Flat on its side','Upside down with the cap open','Sense 1 is a vertical position.','context'),Q(2,'Why is the judge called upright?','He refuses improper gifts','He sits on a high chair','He speaks loudly','Sense 2 concerns moral honesty.','meaning'),Q(3,'Why did she stand upright?','To see over the hedge','To make the hedge taller','To sit down','Sense 3 describes straight posture.','context'),Q(1,'Which phrase is correct?','an upright judge','an uprightly judge','a judge uprightness','Upright is an adjective describing the person.','grammar')]);
P('uprightness','Uprightness adds -ness to upright and names moral honesty and fairness.',C('uprightness.s1','ethics','No one doubted the uprightness of the auditor, who reported the error even though it embarrassed her employer.','没人怀疑审计员的正直；尽管报告错误会让雇主难堪，她仍如实报告。','moral uprightness; admire someone’s uprightness','名词，指诚实、公正而有道德操守的品质。','Reporting the error despite pressure shows integrity.','正直'),M('Her uprightness was clear because she hid the error to protect herself.','Her dishonesty was clear because she hid the error to protect herself.','Hiding the error is dishonest, not upright.','meaning'),[Q(1,'What demonstrated the auditor’s uprightness?','She reported an embarrassing error','She concealed it from everyone','She accepted a gift to stay quiet','Honesty under pressure demonstrates integrity.','context'),Q(1,'Uprightness is…','moral honesty and fairness','a physical height measurement','a building floor','The noun names the quality of being upright in character.','meaning'),Q(1,'Which phrase is idiomatic?','the uprightness of the auditor','the uprightness to the auditor','the auditor uprightnessly','The quality noun is followed by of + person.','grammar'),Q(1,'The suffix -ness turns upright into…','a noun naming a quality','a past-tense verb','a comparative adverb','It names the state or quality of being upright.','word-formation')]);
P('uprising','Uprising is formed from rise with up- and names organized resistance against authority.',[C('uprising.s1','politics','The uprising against the military government was quickly crushed.','反抗军政府的起义很快被镇压。','lead/join an uprising; popular uprising','指人民针对政府或权力机构发动的暴力反抗。','The people resist the ruling authority.','起义'),C('uprising.s2','resistance','There was an uprising in the capital after the police arrested the opposition leader.','警方逮捕反对派领袖后，首都爆发了公开反抗。','an uprising in a city; spark an uprising','指某地爆发的公开抵抗。','The arrest triggers local resistance.','反抗')],M('The uprising against the government consisted of citizens quietly supporting every government order.','The uprising against the government consisted of citizens openly resisting its authority.','Support for every order is not resistance against authority.','meaning'),[Q(1,'Who was the uprising against?','The military government','A neighboring village','The research team','Sense 1 is revolt against governing authority.','context'),Q(2,'What sparked the capital uprising?','Police arrested the opposition leader','The leader won an election','A bridge was repaired','Sense 2 ties the local resistance to the arrest.','context'),Q(1,'An uprising is a form of…','organized resistance','a peaceful holiday','a tax payment','The word denotes rebellion or open resistance.','meaning'),Q(1,'Uprising is related to the verb…','rise','arise upness','upright','It names people rising in resistance.','word-formation')]);
P('upriver','Upriver combines up + river and means situated or moving toward a river’s source.',C('upriver.s1','geography','The village lies upriver from the port, closer to the mountain springs.','这个村庄位于港口上游，更靠近山间泉水。','travel/live upriver; upriver from a port','指位于或朝向河流源头。','The village is closer to the river’s source.','上游'),M('The village is upriver from the port, beside the river mouth where it meets the sea.','The village is downriver from the port, near the river mouth and sea.','The river mouth is downstream, opposite the sourceward direction.','meaning'),[Q(1,'Where is the village relative to the port?','Upstream, nearer the mountain springs','Downstream at the river mouth','Across the ocean','Upriver means toward the source.','context'),Q(1,'A boat traveling upriver moves…','toward the river’s source','toward the sea and river mouth','across a mountain','The direction is upstream.','meaning'),Q(1,'Which phrase is natural?','a village upriver from the port','a village upriver than the port','upriver to the source from at','Upriver from marks relative location.','grammar'),Q(1,'Up- in upriver points toward…','the river’s source','the river mouth','the river bank only','The compound gives an upstream direction.','word-formation')]);
P('uproar','Uproar was borrowed as a loan translation of German Aufruhr or Dutch oproer, literally “a stirring up”; its noisy sense later gained an association with unrelated roar.',[C('uproar.s1','noise','The announcement caused an uproar in the hall, with excited students shouting over one another.','公告在大厅引起一片喧闹，兴奋的学生彼此喊叫。','cause/create an uproar; in an uproar','指由兴奋或愤怒引起的嘈杂混乱。','The hall is noisy and confused.','喧闹'),C('uproar.s2','public reaction','The new tax sparked a public uproar across the region.','新税在整个地区激起了公众强烈不满。','public uproar; provoke an uproar','指公众对某事表现出的强烈愤怒。','People react angrily to the policy.','公愤')],M('The tax caused an uproar, but the public welcomed it quietly and without complaint.','The tax caused an uproar, and the public protested it angrily.','Quiet approval is the opposite of public uproar.','meaning'),[Q(1,'What did the announcement cause in the hall?','Noisy, confused excitement','A silent exam','A power outage','Sense 1 is noisy disorder.','context'),Q(2,'Why was there a public uproar about the tax?','People were strongly angry about it','Nobody knew it existed','It reduced every tax bill','Sense 2 is strong public anger.','meaning'),Q(1,'Which phrase is common?','cause an uproar','drink an uproar','an uproar of a table','Uproar commonly follows cause or create.','collocation'),Q(1,'An uproar can be either…','noise and confusion or public anger','a river current or a hill','a quiet agreement only','The source distinguishes two related senses.','meaning')]);
P('uproot','Uproot combines up + root and means pull a plant out, force people to leave, or eliminate something completely.',[C('uproot.s1','gardening','They uprooted the old hedge before rebuilding the garden wall.','重建花园围墙前，他们把旧树篱连根拔起。','uproot a tree/plant; uproot something from the soil','连根拔起植物。','The roots are removed from the ground.','连根拔起'),C('uproot.s2','migration','The war uprooted thousands of families and forced them to leave their homes.','战争迫使数千个家庭离开家园、流离失所。','war uproots families; be uprooted from home','迫使人们离开家园，迁往别处。','Families lose their homes and must move.','迫使迁离'),C('uproot.s3','customs','The new rules uprooted the old practice of paying workers in cash.','新规定彻底废除了以现金支付工人的旧做法。','uproot a custom/belief; uproot an old system','彻底消除某种习俗、信念或制度。','The former practice is eliminated.','根除')],M('The war uprooted families by helping them remain safely in their own homes.','The war displaced families by forcing them to leave their homes.','Remaining safely at home is not being uprooted.','meaning'),[Q(1,'What did they uproot in the garden?','The old hedge, roots and all','The garden wall only','A bag of seeds','Sense 1 is pulling a plant from the ground.','context'),Q(2,'How did war uproot families?','It forced them to leave home','It gave them new gardens','It repaired their houses','Sense 2 means displace people.','context'),Q(3,'What did the rules uproot?','The old cash-payment practice','A physical hedge','A family home','Sense 3 is eliminating an established practice.','context'),Q(1,'Which phrase is correct?','uproot a tree','uproot a tree into soil to plant it','uproot to the tree','The direct object is the thing removed or eliminated.','grammar')]);
P('upscale','Upscale is formed from up + scale and describes high-quality, expensive goods aimed at affluent buyers.',C('upscale.s1','retail','They opened an upscale hotel by the lake with private dining and spacious suites.','他们在湖边开了一家高档酒店，提供私人餐饮和宽敞套房。','upscale hotel/shop; upscale products','形容词，指高档昂贵、面向富裕消费者的。','The hotel offers premium services at high prices.','高档'),M('The upscale hotel offered the cheapest shared rooms and no services.','The budget hotel offered the cheapest shared rooms and no services.','A premium hotel is not defined by the cheapest basic offer.','meaning'),[Q(1,'What kind of hotel did they open?','A high-quality, expensive hotel','A free public shelter','A low-cost hostel','Upscale targets affluent guests.','context'),Q(1,'An upscale product is generally…','premium and relatively expensive','the cheapest possible','illegal to sell','That is the adjective’s market sense.','meaning'),Q(1,'Choose the correct phrase.','an upscale hotel','an upscalely hotel','a hotel upscale-ness','Upscale is an adjective modifying hotel.','grammar'),Q(1,'Upscale most nearly contrasts with…','budget','premium','luxury','Budget refers to a lower-price market.','meaning')]);
P('upset','Upset comes from up + set, first meaning raise or set up; the overturning, emotional, and stomach senses developed later.',[C('upset.s1','emotion','The news upset her because the flight had been cancelled without warning.','航班毫无预警地取消，这个消息让她难过。','upset someone; be upset about something','使人担心、难过或生气。','The cancellation causes distress.','使难过'),C('upset.s2','objects','He upset a cup of tea when he reached across the crowded table.','他伸手越过拥挤的桌子时打翻了一杯茶。','upset a cup; upset a plan/stomach','打翻东西，也可扰乱计划或使胃不适。','The cup is knocked over.','打翻'),C('upset.s3','health','She felt upset after the rich meal and decided to rest.','吃完油腻大餐后她感到胃不舒服，决定休息。','an upset stomach; feel upset','形容词，指因坏消息或食物而不快或轻微不适。','The meal has made her feel unwell.','不适'),C('upset.s4','competition','The unseeded team’s victory over the champions was a huge upset.','未列种子的球队战胜冠军队，是个大冷门。','a major upset; cause an upset','名词，指出人意料的失败或局势混乱。','The unexpected result surprises observers.','冷门')],M('The match was a major upset, even though the favorite won exactly as everyone had predicted.','The match was not an upset because the favorite won exactly as everyone had predicted.','An upset is an unexpected result; a predicted favorite’s victory is not one.','meaning'),[Q(1,'Why did the news upset her?','Her flight was cancelled without warning','She arrived early for her flight','She chose a new seat','Sense 1 means make someone distressed.','context'),Q(2,'What happened to the cup?','It was knocked over','It was filled with tea','It was put in a cupboard','Sense 2 means overturn an object.','context'),Q(3,'An upset stomach means…','a mildly ill or uncomfortable stomach','a stomach that won a contest','a stomach turned upside down','Sense 3 describes physical discomfort.','meaning'),Q(4,'Why was the victory an upset?','The unseeded team unexpectedly beat the champions','The champions won as expected','The match was cancelled','Sense 4 is a surprising result.','context')]);
P('upshot','Upshot comes from up- + shot; it first meant the final shot in an archery match, then figuratively the result or conclusion.',C('upshot.s1','outcome','The upshot of the budget meeting was that no department received the requested increase.','预算会议的最终结果是没有部门获得所申请的增拨经费。','the upshot of something; in the end, the upshot','指一连串事件或讨论的最终结果。','The meeting ended with a definite outcome.','结果'),M('The upshot of the meeting was its opening greeting, before any discussion began.','The opening of the meeting was its greeting, before any discussion began.','Upshot means final outcome, not the opening moment.','meaning'),[Q(1,'What was the upshot of the meeting?','No department got the requested increase','Every department doubled its budget','The meeting was never held','The upshot is the final result.','context'),Q(1,'The upshot of a long discussion is…','its conclusion or outcome','the first speaker’s greeting','the room’s seating plan','It summarizes what the discussion ultimately produced.','meaning'),Q(1,'Which expression is natural?','the upshot of the decision','the upshot at the decision to','the decision upshotly','The usual pattern is upshot of something.','grammar'),Q(1,'Upshot is closest to…','outcome','beginning','argument only','It names the final result.','meaning')]);
P('upside','Upside names an advantage or good consequence; it can also name an object’s top face.',[C('upside.s1','advantages','The upside of the delay was that the team gained an extra day to rehearse.','延误的好处是团队多了一天排练时间。','the upside of something; look on the upside','指有利的一面或积极后果，也可指物体上面。','The delay produces a useful extra day.','好处'),C('upside.s1','objects','Place the card upside facing upward so the printed side is visible.','把卡片正面朝上放置，让印刷的一面可见。','the upside of a surface; turn upside up','指物体朝上的一面。','The printed face is the top side.','上面')],M('The upside of the delay was that the team lost all rehearsal time.','The downside of the delay was that the team lost all rehearsal time.','Losing rehearsal time is a disadvantage, or downside.','meaning'),[Q(1,'What was the upside of the delay?','An extra day to rehearse','A lost day of rehearsal','A cancelled performance','The upside is the positive consequence.','context'),Q(1,'The upside of a card is…','the face positioned on top','its hidden thickness','the bottom edge only','The literal sense is the upper face.','meaning'),Q(1,'Which phrase is natural?','the upside of waiting','the upside to waitingly','an upside waiting of','The pattern is the upside of + noun/gerund.','grammar'),Q(1,'Upside is often contrasted with…','downside','inside','outside','Downside names the disadvantage.','meaning')]);
P('upside-down','Upside-down is a compound modifier meaning turned so the top is underneath, or thoroughly disordered.',C('upside-down.s1','orientation','The painting was hung upside-down, with the artist’s signature at the top edge.','画作被上下颠倒地挂着，艺术家的签名在上边缘。','hang/turn something upside-down; upside-down image','指上部朝下的，也可形容彻底混乱。','The top of the painting faces downward.','上下颠倒'),M('The painting hung upside-down with its top edge above its bottom edge.','The painting hung upright with its top edge above its bottom edge.','That orientation is upright, not upside-down.','meaning'),[Q(1,'How was the painting hung?','With its top turned underneath','Upright on the floor','Flat inside a drawer','Upside-down reverses the normal orientation.','context'),Q(1,'An upside-down picture has…','its top below its bottom','its top above its bottom','no top edge','The compound names reversed orientation.','meaning'),Q(1,'Which spelling is standard?','upside-down','upside down as a single adjective before a noun','upside-downly','The hyphenated compound is standard as an adjective.','spelling'),Q(1,'If a schedule is upside-down figuratively, it is…','completely disordered','perfectly organized','made of paper','The figurative sense means thoroughly confused.','meaning')]);
P('upstairs','Upstairs combines up + stairs and can indicate movement to a higher floor, location there, or the upper floor itself.',[C('upstairs.s1','movement','She went upstairs to sleep after locking the front door.','锁好前门后，她上楼去睡觉。','go/run/walk upstairs; come upstairs','指朝楼上移动。','She moves to a higher floor.','上楼'),C('upstairs.s2','location','The upstairs rooms are quieter because they face the garden.','楼上的房间更安静，因为它们朝向花园。','upstairs bedroom/office; live upstairs','作形容词或副词，指位于上层。','The rooms are located above the ground floor.','楼上的'),C('upstairs.s3','place','The upstairs needs painting before the new tenants arrive.','新租户到来前，楼上区域需要重新粉刷。','the upstairs; paint/clean upstairs','名词，指地面层以上的一层或几层。','It refers to the upper floor area.','楼上区域')],M('She went upstairs to the basement below the ground floor.','She went downstairs to the basement below the ground floor.','The basement is below ground; upstairs is toward a higher floor.','meaning'),[Q(1,'Where did she go to sleep?','To a higher floor','Into the basement','Out to the garden','Sense 1 is movement upward in a building.','context'),Q(2,'Why are the upstairs rooms quieter?','They face the garden','They are below the kitchen','They have no walls','Sense 2 describes their location.','context'),Q(3,'What needs painting?','The upper-floor area','The street outside','The roof only','Sense 3 uses upstairs as a noun.','meaning'),Q(1,'Which phrase is correct?','go upstairs','go to upstairs','go upstairsly','Upstairs is an adverb without to.','grammar')]);
P('upsurge','Upsurge combines up + surge and means a rapid rise in an amount or level of activity.',C('upsurge.s1','statistics','The college saw an upsurge in applications after it added a nursing program.','学院开设护理专业后，申请人数迅速增加。','an upsurge in demand/activity; see an upsurge','名词，指数量、情绪或活动的快速上升。','Applications rise rapidly.','激增'),M('The upsurge in applications meant that applications fell sharply each month.','The decline in applications meant that applications fell sharply each month.','A fall is a decline, opposite of an upsurge.','meaning'),[Q(1,'What caused the upsurge in applications?','The college added a nursing program','The college closed every program','Tuition became unavailable','The new program preceded a rapid rise.','context'),Q(1,'An upsurge is…','a rapid increase','a gradual disappearance','a stable level','The word means a sudden rise.','meaning'),Q(1,'Choose the usual pattern.','an upsurge in demand','an upsurge of demandedly','demand upsurge to','Upsurge is commonly followed by in + noun.','grammar'),Q(1,'Which verb pairs naturally with upsurge?','see','drink','fold','A report may say a market saw an upsurge.','collocation')]);
P('upturn','Upturn combines up + turn and names an improvement in trade, business, or activity.',C('upturn.s1','economics','The local shops have shown an upturn in sales since the new station opened.','新车站开放后，当地商店的销售额有所回升。','economic upturn; show/see an upturn','名词，指贸易、商业或活动水平的改善。','Sales are improving after a weak period.','回升'),M('The upturn in sales meant shops sold fewer goods every month.','The downturn in sales meant shops sold fewer goods every month.','Falling sales indicate a downturn, not an upturn.','meaning'),[Q(1,'What improved after the station opened?','Sales at local shops','The number of closed shops','The weather','An upturn is improvement in business activity.','context'),Q(1,'An economic upturn is…','a recovery or improvement','a sudden collapse','a fixed tax rate','The term indicates rising activity.','meaning'),Q(1,'Which collocation is natural?','a business upturn','an upturn of sleeping','upturn into a desk','The noun commonly combines with business/economic.','collocation'),Q(1,'Upturn is the opposite of…','downturn','upward','increase','A downturn is a decline in activity.','meaning')]);
P('upward','Upward comes from up + -ward, describing movement or direction toward a higher level or place.',[C('upward.s1','trend','The chart shows an upward trend in rent prices over the past year.','图表显示过去一年租金呈上升趋势。','upward trend/movement; upward pressure','表示向更高位置或水平移动、发展的。','The prices rise over time.','上升'),C('upward.s2','direction','She glanced upward when the bell rang above her.','头顶的铃响时，她朝上看去。','look/glance upward; point upward','作副词，表示朝更高处或超过某数量。','Her gaze moves toward a higher place.','向上')],M('The chart showed an upward trend because prices fell every month.','The chart showed a downward trend because prices fell every month.','Falling prices show a downward, not upward, trend.','meaning'),[Q(1,'What trend did the chart show?','Rent prices rose','Rent prices fell each month','Prices stayed exactly fixed','Sense 1 describes a rise in level.','context'),Q(2,'Why did she glance upward?','A bell rang above her','The floor opened beneath her','A sound came from the road','Sense 2 gives direction toward a higher place.','context'),Q(1,'Which phrase is natural?','an upward trend','an upwardly trend','a trend upword','Upward functions as an adjective before trend.','grammar'),Q(1,'Upward is formed with the directional suffix…','-ward','-ness','-less','The suffix marks direction.','word-formation')]);
P('upwards','Upwards is upward with an adverbial -s, meaning toward a higher position or beyond a stated number.',[C('upwards.s1','direction','The path climbs upwards from the village toward the mountain pass.','小路从村庄向上延伸，通往山口。','move/look upwards; point upwards','副词，指向更高的位置、水平或方向移动。','The path rises toward higher ground.','向上'),C('upwards.s2','quantity','The hall admits groups aged twelve and upwards, but not younger children.','大厅接待十二岁及以上的团体，但不接待更小的孩子。','twelve and upwards; ages upwards of','表示超过某个数量或年龄。','The lower age limit is twelve.','及以上')],M('The event is for children aged twelve and upwards, so five-year-olds meet the age rule.','The event is for children aged twelve and upwards, so only those at least twelve meet the age rule.','Five is below the stated minimum of twelve.','meaning'),[Q(1,'Where does the path lead?','Toward higher ground','Down to the sea','Across a flat plain','Sense 1 indicates upward direction.','context'),Q(2,'Who may enter under the age rule?','People aged twelve or older','Only children under twelve','Only adults over eighty','Sense 2 means at least twelve.','meaning'),Q(1,'Which phrase is natural?','look upwards','look upwardsly','look to upwards at','Upwards is an adverb of direction.','grammar'),Q(2,'“Twelve and upwards” means…','twelve or more','twelve or fewer','exactly twelve only','The expression includes twelve and higher ages.','meaning')]);
P('upwelling','Upwelling combines up + well (rise) and names the upward movement of deeper ocean water.',C('upwelling.s1','oceanography','Coastal upwelling carries cold, nutrient-rich water toward the surface and supports abundant fish.','沿海上升流把寒冷且富含营养的深层海水带到表面，支撑了丰富渔业。','coastal upwelling; ocean upwelling','名词，指深层海水向上运动，通常发生在海岸附近。','Deep water rises to the surface.','上升流'),M('Coastal upwelling carries surface water down into the ocean depths.','Coastal downwelling carries surface water down into the ocean depths.','Upwelling moves deeper water upward, not surface water downward.','meaning'),[Q(1,'What does coastal upwelling carry upward?','Cold, nutrient-rich deep water','Warm sand from the beach','Clouds from the mountains','The oceanographic process brings deep water to the surface.','context'),Q(1,'Where does upwelling often occur?','Along a coast','Inside a dry cave','On a city street','The sense commonly describes coastal ocean water.','meaning'),Q(1,'Which term is correct?','ocean upwelling','ocean upwellingly','upwelling of ocean to down','Upwelling names a process in the ocean.','collocation'),Q(1,'The compound’s up- suggests water moves…','toward the surface','toward the seabed','sideways only','Upwelling is upward movement.','word-formation')]);
P('upwind','Upwind combines up + wind and describes the direction from which wind comes or the side facing it.',C('upwind.s1','environment','The camp was set upwind of the factory so smoke would blow away from the tents.','营地设在工厂的上风处，这样烟就会从帐篷吹向别处。','upwind of a source; stand/travel upwind','指位于或朝向风吹来的那一侧。','The wind carries smoke away from camp.','上风处'),M('The camp was upwind of the factory, so the wind carried factory smoke directly toward it.','The camp was downwind of the factory, so the wind carried factory smoke toward it.','If smoke blows toward camp, it is downwind of the source.','meaning'),[Q(1,'Why was the camp placed upwind?','The smoke would blow away from the tents','The factory would be closer','The tents needed more smoke','Upwind is the side from which wind comes.','context'),Q(1,'If you stand upwind of a fire, the wind blows…','from you toward the fire','from the fire toward you','straight down from the sky','Upwind is on the incoming-wind side.','meaning'),Q(1,'Which preposition is used in the phrase?','upwind of the factory','upwind at the factory','upwind to the factory','The common pattern is upwind of.','grammar'),Q(1,'Upwind contrasts with…','downwind','upright','upward','Downwind is the side toward which wind travels.','meaning')]);
P('uranium','Uranium was named in 1789 after the recently discovered planet Uranus; it is a heavy radioactive metal used as nuclear fuel or raw material.',[C('uranium.s1','energy','Uranium is processed into fuel for some nuclear power plants.','铀经过加工后可用作一些核电站的燃料。','uranium fuel; uranium ore; uranium-235','名词，指符号为 U 的重放射性金属，可作核燃料。','The metal is used in nuclear energy.','铀'),C('uranium.s2','trade','The region exports uranium ore that is mined and processed under strict safety rules.','该地区出口在严格安全规范下开采并加工的铀矿石。','mine/export uranium; uranium as a raw material','指作为矿产原料开采和贸易的铀。','The material is extracted and sold.','铀矿原料')],M('Uranium is a harmless nonmetal used mainly to make paper.','Uranium is a radioactive metal used as nuclear fuel.','Uranium is a radioactive metal, not a harmless paper-making nonmetal.','meaning'),[Q(1,'What is uranium used for in the first context?','Fuel for nuclear power plants','Paper production','Road paving','Sense 1 is the radioactive metal used in nuclear energy.','context'),Q(2,'What does the region export?','Mined uranium ore','Finished paper','A type of coal stove','Sense 2 concerns the metal as a traded raw material.','context'),Q(1,'What is uranium’s chemical symbol?','U','Ur','Un','The element uranium has symbol U.','meaning'),Q(1,'The element was named after…','the planet Uranus','the city of Rome','the word urban','Its name followed the discovery of Uranus.','word-formation')]);
P('Uranus','Uranus is the Latinized name of the Greek sky god Ouranos and the seventh planet from the Sun.',[C('Uranus.s1','astronomy','Uranus is a pale-blue giant planet, notable for rotating with an extreme sideways tilt.','天王星是一颗淡蓝色巨行星，以近乎侧躺的自转倾角著称。','the planet Uranus; orbit Uranus','专名，指太阳系中距太阳第七远的行星。','The sentence describes the planet’s color and tilt.','天王星'),C('Uranus.s2','mythology','In Greek myth, Uranus was the sky god and father of the Titans.','在希腊神话中，乌拉诺斯是天空之神，也是泰坦诸神之父。','the god Uranus; Greek myth of Uranus','专名，指希腊神话中的天空之神。','This is the mythological figure, not the planet.','乌拉诺斯')],M('Uranus is the fifth planet from the Sun, located between Earth and Mars.','Uranus is the seventh planet from the Sun, beyond Saturn.','Uranus is seventh; it is beyond Saturn, not between Earth and Mars.','meaning'),[Q(1,'What is Uranus in astronomy?','The seventh planet from the Sun','The fifth planet between Earth and Mars','A moon of Jupiter','Sense 1 names the planet.','meaning'),Q(2,'Who was Uranus in Greek myth?','The sky god and father of the Titans','A Roman emperor','The god of the sea','Sense 2 is the mythic sky deity.','context'),Q(1,'How is the planet’s name conventionally capitalized?','Uranus','uranus','URanus','Planet names are proper nouns and take an initial capital.','capitalization'),Q(1,'Uranium was named after…','Uranus','the Moon','Mars','The element’s name was coined after the planet.','word-formation')]);
P('urban','Urban comes from Latin urbanus, “of the city,” and means of, in, or characteristic of a city.',[C('urban.s1','location','Urban traffic is heaviest near the station during the morning commute.','早高峰期间，车站附近的城市交通最为拥堵。','urban area/traffic; urban population','指位于城市中的。','The traffic is inside the city.','城市的'),C('urban.s2','society','The report examines urban problems such as housing costs and crowded buses.','报告研究住房成本和公交拥挤等城市问题。','urban life/issues; urban growth','指典型的城市生活、人口或问题。','The issues are associated with city populations.','城市特有的')],M('Urban traffic is traffic on a remote farm with no town nearby.','Rural traffic is traffic on a remote farm with no town nearby.','A remote farm is rural rather than urban.','meaning'),[Q(1,'Where is the traffic described as urban?','Near the city station','On a remote farm','In an uninhabited desert','Sense 1 means in a city.','context'),Q(2,'Which problems are urban in the report?','Housing costs and crowded buses','Ocean currents and coral bleaching','Mountain snowfall only','Sense 2 covers issues characteristic of city life.','context'),Q(1,'Which phrase is natural?','urban population','urbanly population','population urbanity','Urban is an adjective modifying population.','grammar'),Q(1,'Urban traces back to Latin…','urbanus, “of the city”','unda, “wave”','unus, “one”','The source refers to city life.','word-formation')]);
P('urbane','Urbane comes through French from Latin urbanus, “of the city,” and describes polished, courteous social manners.',C('urbane.s1','conversation','Even after the insult, he gave an urbane reply and changed the subject politely.','即使受到侮辱，他仍礼貌得体地回应，并客气地转移话题。','urbane manner/reply; urbane and courteous','形容词，指举止文雅、圆融有礼。','His composed politeness shows social ease.','文雅'),M('His urbane reply was a shouted insult that embarrassed every guest.','His rude reply was a shouted insult that embarrassed every guest.','A shouted insult is rude, not polished and courteous.','meaning'),[Q(1,'How did he reply to the insult?','With polished courtesy','By shouting another insult','By leaving without a word','Urbane means socially smooth and courteous.','context'),Q(1,'An urbane host is likely to be…','gracious and socially polished','crude and hostile','unable to speak','The adjective describes refined manner.','meaning'),Q(1,'Which phrase is correct?','an urbane reply','an urbanely reply','a reply urbane-ness','Urbane is an adjective before a noun.','grammar'),Q(1,'Urbane is historically related to…','Latin urbanus, “of the city”','Latin ursus, “bear”','Greek ouranos, “sky”','Both words trace to the Latin word for city.','word-formation')]);
P('urbanism','Urbanism is built from urban + -ism and names the character of city life or the study/practice of urban planning.',C('urbanism.s1','planning','Her research on postwar urbanism compares street layouts and public spaces in three cities.','她对战后城市主义的研究比较了三座城市的街道布局和公共空间。','urbanism studies; modern urbanism; urban planning','名词，指城市生活的特征或城市规划实践。','The research analyzes how cities are organized and lived in.','城市主义'),M('Her urbanism study examined only the grammar of ancient poems and no cities.','Her philology study examined the grammar of ancient poems and no cities.','A study of city form and life is urbanism, not philology.','meaning'),[Q(1,'What does her urbanism research compare?','Street layouts and public spaces','Verb endings in ancient poems','Ocean temperatures','Urbanism concerns city form and life.','context'),Q(1,'Urbanism can mean…','the character of city life or urban planning','a single city resident','a type of rural crop','The noun covers city life and its planning.','meaning'),Q(1,'Which phrase is natural?','postwar urbanism','urbanismly city','urbanisms to planning','Urbanism is a noun for a field or city pattern.','grammar'),Q(1,'The suffix -ism commonly forms…','a noun naming a practice or system','a past tense','a comparative adjective','Urbanism names a practice or broad character.','word-formation')]);
P('urbanite','Urbanite combines urban + -ite and means a person accustomed to living in a large city.',C('urbanite.s1','lifestyle','The urbanite took the subway to work and had never driven on a country road.','这位城市居民乘地铁上班，从未在乡间道路上开过车。','city urbanite; lifelong urbanite','名词，指生活在大城市并熟悉城市生活的人。','The person’s habits reflect city residence.','城市居民'),M('The urbanite had lived on a remote farm all his life and had never visited a city.','The rural resident had lived on a remote farm all his life and had never visited a city.','A lifelong farm resident is not accustomed to large-city life.','meaning'),[Q(1,'What suggests the person is an urbanite?','He commutes by subway and has not driven country roads','He farms sheep far from town','He lives in a lighthouse','An urbanite is used to city life.','context'),Q(1,'An urbanite is…','a person accustomed to a large city','a city-planning law','a kind of city bus','The suffix -ite forms a person noun here.','meaning'),Q(1,'Which plural is standard?','urbanites','urbanitys','urbanitees','The regular plural adds -s.','grammar'),Q(1,'Urbanite contrasts most directly with…','rural resident','city commuter','subway rider','A rural resident lives outside urban settings.','meaning')]);
P('urbanity','Urbanity is formed from urban + -ity and names refined manners and social grace.',C('urbanity.s1','manners','He accepted the sharp criticism with urbanity, thanking the speaker for the useful point.','他优雅从容地接受尖锐批评，并感谢发言者提出有用观点。','charm/urbanity; display urbanity','名词，指文雅举止和从容的社交风度。','His gracious response shows social ease.','文雅风度'),M('He showed urbanity by shouting insults and throwing the speaker’s notes.','He showed rudeness by shouting insults and throwing the speaker’s notes.','Insults and aggression show rudeness, not urbanity.','meaning'),[Q(1,'How did he accept criticism?','Graciously and politely','By throwing the notes','By leaving angrily','Urbanity is refined social grace.','context'),Q(1,'Urbanity refers to…','polished manners and social ease','a city’s population count','a person’s home address','The word names a quality of manner.','meaning'),Q(1,'Complete: He responded with ___.','urbanity','urbane','urbanely','The preposition with takes the noun urbanity, not an adjective or adverb.','grammar'),Q(1,'The suffix -ity forms…','a noun naming a quality','a verb tense','a place name','Urbanity names the quality of being urbane.','word-formation')]);
P('urbanization','Urbanization is urban + -ization, the process of cities growing or city development spreading into rural areas.',[C('urbanization.s1','demography','Rapid urbanization has changed the countryside as more people move into towns and cities.','随着更多人迁入城镇和城市，快速城市化改变了乡村。','rapid urbanization; rate of urbanization','指城镇扩张、更多人口居住在城市的过程。','Population shifts toward urban areas.','城市化'),C('urbanization.s2','land use','Urbanization is consuming farmland as roads and housing spread beyond the city edge.','道路和住宅向城市边缘以外扩展，城市化正在占用农田。','urbanization of the countryside; urban sprawl','指城市建筑和生活方式向乡村地区扩展。','Built areas spread into rural land.','城市扩张')],M('Urbanization changed the region because everyone left the cities and moved to farms.','Ruralization changed the region because people left the cities and moved to farms.','Movement away from cities is not urbanization.','meaning'),[Q(1,'Why has the countryside changed?','More people are moving into towns and cities','Everyone is moving to isolated farms','No one is changing residence','Sense 1 concerns population shift to cities.','context'),Q(2,'What is consuming farmland?','Roads and housing spreading beyond the city','Fields shrinking because of drought only','A river moving upstream','Sense 2 describes urban development spreading outward.','context'),Q(1,'Complete: Rapid ___ has changed the countryside.','urbanization','urbanize','urbanly','The sentence needs the process noun after rapid.','grammar'),Q(1,'Urbanization generally means…','growth or spread of urban areas','a decline in every city population','the restoration of a forest only','It is the process of becoming more urban.','meaning')]);
P('urbanize','Urbanize is urban + -ize and means make a place urban or cause people to adopt city ways.',C('urbanize.s1','development','New roads and apartment blocks urbanized the valley within a decade.','新道路和公寓楼在十年内使山谷逐渐城市化。','urbanize a region; become urbanized','使乡村地区变成城市地区，也可使人采用城市生活方式。','Development turns the valley into an urban area.','使城市化'),M('They urbanized the valley by removing every road and returning the land to wilderness.','They rewilded the valley by removing roads and restoring wilderness.','Removing development is rewilding, not urbanizing.','meaning'),[Q(1,'What urbanized the valley?','Roads and apartment blocks','A ban on buildings','A new wilderness reserve','The construction changed the rural valley into urban land.','context'),Q(1,'To urbanize a village is to…','make it more like a city','remove all city services','move it to another planet','Urbanize means turn into or make urban.','meaning'),Q(1,'Which verb form is correct?','The town urbanized the valley.','The town urbanize the valley yesterday.','The town urbanizated the valley.','Urbanize forms its past as urbanized.','grammar'),Q(1,'The suffix -ize often means…','make or cause to become','a person who lives somewhere','a quality or state only','Urbanize means make urban.','word-formation')]);
P('urchin','Urchin comes through Anglo-French from a word for hedgehog; it can mean a poor or mischievous child or a spiny sea animal.',[C('urchin.s1','children','A group of street urchins played football in the alley while adults watched nearby.','一群街头顽童在巷子里踢足球，成年人在附近看着。','street urchin; mischievous urchin','旧式或文学用法，指贫穷、淘气的孩子。','The children play noisily in the street.','顽童'),C('urchin.s2','marine life','Sea urchins hide among the rocks at low tide, their spines protecting them.','退潮时海胆躲在岩石间，尖刺保护着它们。','sea urchin; spiny urchin','名词，指身体呈圆形、长满尖刺的小型海洋动物。','The marine animal has protective spines.','海胆')],M('The sea urchin was a soft bird with feathers and wings.','The sea urchin was a spiny marine animal among the rocks.','A sea urchin is an animal with spines, not a feathered bird.','meaning'),[Q(1,'Who played football in the alley?','Street urchins','Sea animals','The adults only','Sense 1 is an old-fashioned term for a poor or naughty child.','context'),Q(2,'What protects sea urchins?','Their spines','Feathers','A hard shell of paper','Sense 2 is the spiny marine animal.','context'),Q(1,'Which expression is common?','sea urchin','river urchin for a hedgehog','urchin of the weather','The marine sense commonly appears in sea urchin.','collocation'),Q(1,'The older child sense is often…','literary or old-fashioned','a formal job title','a scientific name for a bird','The term can sound old-fashioned when applied to a child.','register')]);
P('urge','Urge comes from Latin urgere, “press”; as a verb it means strongly persuade or publicly recommend, and as a noun a powerful impulse.',[C('urge.s1','advice','We urged her to see a doctor when the fever did not fall.','高烧不退时，我们力劝她去看医生。','urge someone to do something; urge caution','强烈劝说某人采取行动。','They press her to seek care.','力劝'),C('urge.s2','advocacy','The report urges the government to repair the bridge before winter.','报告敦促政府在冬天前修好桥梁。','report urges action; urge that something be done','公开强调某项行动有必要。','The report recommends a necessary course.','敦促'),C('urge.s3','impulse','I felt an urge to laugh when the solemn speaker mispronounced the name.','严肃的发言者把名字读错时，我忍不住想笑。','an urge to do something; resist an urge','强烈且难以控制的愿望。','The speaker feels a sudden impulse.','冲动')],M('The report urged the government to delay repairs, meaning it said repairs were unnecessary and should not happen.','The report urged the government to make repairs, meaning it strongly recommended that action.','To urge an action is to recommend or press for it, not say it is unnecessary.','meaning'),[Q(1,'What did the group urge her to do?','See a doctor','Ignore the fever','Cancel her appointment','Sense 1 is strong persuasion.','context'),Q(2,'What does the report urge?','Repair the bridge before winter','Leave the bridge unrepaired','Close every government office','Sense 2 is a public recommendation for action.','context'),Q(3,'An urge to laugh is…','a strong impulse','a formal report','a physical bridge','Sense 3 is a powerful desire.','meaning'),Q(1,'Choose the usual pattern.','urge someone to act','urge someone for act','urge to someone acting','Urge + person + to-infinitive is standard.','grammar')]);
P('urgency','Urgency is formed from urgent + -cy and names the need for quick action or an insistent request.',[C('urgency.s1','medicine','Doctors stressed the urgency of the operation because the infection was spreading.','由于感染正在扩散，医生强调手术必须尽快进行。','urgency of a situation; with great urgency','指因危险或重要性而需要迅速处理。','Delay could worsen the infection.','紧迫性'),C('urgency.s2','requests','The mayor’s message carried urgency: every household had to boil water immediately.','市长的信息语气急迫：每户人家必须立即烧开饮用水。','a sense of urgency; convey urgency','指强烈要求立即采取行动。','The public is asked to act at once.','急切要求')],M('The doctor stressed the urgency of treatment but said it could safely wait several months.','The doctor said treatment was not urgent and could wait several months.','A need for immediate action conflicts with waiting months.','meaning'),[Q(1,'Why was the operation urgent?','The infection was spreading','The patient wanted a holiday','The hospital was closing next year','Sense 1 concerns danger requiring quick action.','context'),Q(2,'What did the mayor’s message demand?','Boil water immediately','Wait several months','Stop reading notices','Sense 2 is an insistent request for prompt action.','context'),Q(1,'Urgency is…','the need for quick action','a permanent building','a type of medicine','The noun names the quality of being urgent.','meaning'),Q(1,'Which phrase is natural?','a sense of urgency','urgencyly report','an urgency to quickly action','The common collocation is a sense of urgency.','collocation')]);
P('urgent','Urgent comes from Latin urgentem, “pressing”; it describes something requiring immediate attention or a speaker’s insistent tone.',[C('urgent.s1','priority','The letter is urgent because the application deadline is at noon today.','这封信很紧急，因为申请截止时间是今天中午。','urgent matter/request; urgent attention','指重要到必须立即处理的。','The deadline leaves little time.','紧急'),C('urgent.s2','tone','She spoke in an urgent whisper and asked us to leave the building at once.','她用急切的低声说话，要求我们立刻离开大楼。','urgent tone/voice; sound urgent','形容说话方式显示希望对方马上行动。','Her voice conveys insistence and immediacy.','急切')],M('The urgent deadline was six months away, so nobody needed to act soon.','The distant deadline was six months away, so nobody needed to act soon.','A matter requiring immediate action cannot wait six months.','meaning'),[Q(1,'Why is the letter urgent?','The deadline is at noon today','The application closed last year','The envelope is blue','Sense 1 is a matter needing prompt action.','context'),Q(2,'What did her urgent whisper communicate?','Leave the building immediately','Stay for another week','Speak more slowly','Sense 2 is an insistent tone.','context'),Q(1,'Which collocation is natural?','urgent attention','urgently attention','attention urgentness','Urgent is an adjective modifying attention.','grammar'),Q(1,'Urgent originally carries the idea of…','pressing for immediate action','being ornamental','being far away','Its Latin source means pressing.','word-formation')]);
P('urine','Urine comes from Latin urina and names the liquid waste made by the kidneys, including a sample tested for illness.',[C('urine.s1','biology','The kidneys remove waste from the blood and produce urine, which is stored in the bladder.','肾脏从血液中过滤废物并产生尿液，尿液储存在膀胱中。','produce/pass urine; urine sample','指肾脏产生并储存在膀胱中的液体废物。','It is part of the body’s waste system.','尿液'),C('urine.s2','medicine','The laboratory found traces of blood in the urine sample and asked for another test.','实验室在尿样中发现微量血液，因此要求再做一次检查。','test urine; blood/protein in the urine','指作为疾病检查对象的尿液。','The sample is analyzed for a medical sign.','尿样')],M('The lab tested urine, the liquid made by the lungs and stored in the stomach.','The lab tested urine, the liquid made by the kidneys and stored in the bladder.','Urine is produced by the kidneys and stored in the bladder.','meaning'),[Q(1,'Which organs produce urine?','The kidneys','The lungs','The stomach','Sense 1 identifies the body’s source of urine.','meaning'),Q(2,'What did the laboratory find?','Traces of blood in a urine sample','A broken bone in the urine','Sugar in a lung sample','Sense 2 concerns medical testing of urine.','context'),Q(1,'Which phrase is correct?','a urine sample','an urine sample','urine sampleses','Urine begins with a consonant sound and is usually uncountable.','grammar'),Q(1,'Urine is stored in the…','bladder','lungs','stomach','The source sense says it is stored in the bladder.','meaning')]);
P('urn','Urn comes from Latin urna and names a rounded vessel used decoratively, for cremated remains, or for hot drinks.',C('urn.s1','vessel','Voters dropped their paper ballots into the urn beside the polling-station door.','选民把纸质选票投入投票站门旁的票箱。','ballot urn; tea urn; funerary urn','名词，指带底座的圆腹容器，可用于装饰、骨灰或热饮。','The rounded vessel receives ballots here.','瓮/票箱'),M('The voters put ballots into the urn, a flat piece of paper with no container.','The voters put ballots into the urn, a rounded vessel used to collect them.','An urn is the container, not the paper ballot.','meaning'),[Q(1,'What did voters place in the urn?','Paper ballots','A voting booth','A cup of tea only','The vessel collected ballots.','context'),Q(1,'A funerary urn may hold…','cremated remains','fresh bread dough','a legal document only','One source sense is a vessel for ashes.','meaning'),Q(1,'Which phrase is natural?','a tea urn','an urnful of tea as the only standard form','a urn of tea','Urn is a count noun taking the article a.','grammar'),Q(1,'Which Latin source is associated with urn?','urna','urbs','urina','Urn derives from Latin urna, a vessel.','word-formation')]);
P('us','Us is inherited from Old English ūs, the dative/accusative form of we, and remains the standard object form; colloquial speech also uses it as a subject.',[C('us.s1','pronouns','Please wait for us outside the library until the meeting ends.','请在图书馆外等我们，直到会议结束。','wait for us; give us something; between us','宾格代词，指包括说话者在内的一群人作宾语。','The group is the object of wait for.','我们（宾格）'),C('us.s2','informal speech','“Us two can finish the display,” Max said, using a common informal subject form.','马克斯说“咱俩能把展览布置完”，这里用了常见的非正式主语形式。','informal “us two”; standard form “we two”','非正式口语中有时用作 we 应出现的主语。','The informal utterance uses us before the verb.','我们（口语主格）')],M('The guide spoke to we after the tour.','The guide spoke to us after the tour.','A preposition such as to takes the object form us.','grammar'),[Q(1,'In “wait for us,” us is…','the object of the preposition for','the verb’s subject','a possessive adjective','Us is the object form of we.','grammar'),Q(2,'In the informal quote, what does “us two” mean?','The speaker and Max, as a subject','Two people excluding the speaker','A possessive phrase','The source notes colloquial subject use.','context'),Q(1,'Choose the standard sentence.','They invited us to dinner.','They invited we to dinner.','Us invited them to dinner.','The object of invited is us.','grammar'),Q(2,'Which subject form is standard in formal English?','We two can finish.','Us two can finish.','Us can finishes.','The source labels us as subject only in informal usage.','register')]);
P('usable','Usable is use + -able and describes something in a condition that allows it to be used.',C('usable.s1','data','The data are usable once the missing dates have been filled in.','缺失日期补齐后，这些数据就可以使用了。','usable data/equipment; make something usable','形容词，指处于可供使用的状态。','Completing the dates makes the data workable.','可用'),M('The data are usable, but every file is corrupted and cannot be opened.','The data are unusable because every file is corrupted and cannot be opened.','Files that cannot be opened are not in usable condition.','meaning'),[Q(1,'What makes the data usable?','Filling in the missing dates','Deleting every file','Changing the researcher’s name','The repair makes the data fit for use.','context'),Q(1,'A usable tool is…','in a condition that allows use','certain to be expensive','already thrown away','Usable means capable of being used.','meaning'),Q(1,'Which phrase is correct?','usable data','usably data','data useablely','Usable is an adjective before data.','grammar'),Q(1,'The suffix -able means…','capable of being used','without any use','used in the past only','Use + -able means fit or able to be used.','word-formation')]);
})(typeof window!=='undefined'?window:globalThis);




